(window.CARDS = window.CARDS || {}).food = [{"name":"Пицца","emoji":"🍕","meta":["итальянская кухня","основное блюдо"],"description":"Лепёшка из дрожжевого теста с томатным соусом, сыром и начинкой, которую запекают в печи до хрустящей корочки. Появилась в Неаполе, а сейчас это одно из самых узнаваемых блюд в мире с бесчисленным количеством вариаций начинки.","fact":"По распространённой версии, пицца «Маргарита» названа в честь итальянской королевы, а её цвета повторяют флаг Италии.","wiki_en":"Pizza"},{"name":"Суши","emoji":"🍣","meta":["японская кухня","основное блюдо"],"description":"Блюдо из приправленного уксусом риса, которое сочетают с рыбой, морепродуктами или овощами. В Японии существует множество разновидностей — от нигири до роллов, а сама идея изначально возникла как способ консервировать рыбу в рисе.","fact":"Слово «суши» относится именно к рису с уксусом, а не к рыбе — блюдо может быть даже полностью вегетарианским.","wiki_en":"Sushi"},{"name":"Бургер","emoji":"🍔","meta":["американская кухня","основное блюдо"],"description":"Булочка с котлетой из говяжьего фарша, сыром, овощами и соусами — одно из главных блюд фастфуда во всём мире. Появился в США на рубеже XIX–XX веков и быстро стал символом американской кулинарной культуры.","fact":"Название «гамбургер» происходит от немецкого города Гамбург, откуда переселенцы привезли рецепт рубленых котлет.","wiki_en":"Hamburger"},{"name":"Паста карбонара","emoji":"🍝","meta":["итальянская кухня","основное блюдо"],"description":"Паста с соусом из яиц, твёрдого сыра, гуанчале и чёрного перца, без сливок в классическом рецепте. Блюдо родом из Рима, а кремовую текстуру соус получает благодаря взбитым яйцам, а не термической обработке сливок.","fact":"О происхождении названия спорят — по одной из версий, оно связано с угольщиками, которых блюдо якобы кормило в горах.","wiki_en":"Carbonara"},{"name":"Паста болоньезе","emoji":"🍝","meta":["итальянская кухня","основное блюдо"],"description":"Паста с мясным соусом рагу на основе говяжьего фарша, томатов, овощей и вина, который долго томится на медленном огне. Классический рецепт из Болоньи традиционно подают не со спагетти, а с широкой лапшой тальятелле.","fact":"В Италии соус рагу к спагетти почти не подают — более правильным сочетанием там считают тальятелле.","wiki_en":"Bolognese sauce"},{"name":"Лазанья","emoji":"🍝","meta":["итальянская кухня","основное блюдо"],"description":"Слоёная запеканка из листов пасты, мясного или овощного соуса, бешамеля и сыра, которую готовят в духовке до румяной корочки. Блюдо происходит из региона Эмилия-Романья и считается одним из старейших видов пасты в Италии.","fact":"Похожие на лазанью блюда из слоёв теста описаны уже в кулинарных рукописях XIV века — и итальянских, и английских.","wiki_en":"Lasagne"},{"name":"Ризотто","emoji":"🍚","meta":["итальянская кухня","основное блюдо"],"description":"Кремовое блюдо из риса, который медленно варят в бульоне, постоянно помешивая и постепенно добавляя жидкость. Один из самых известных вариантов — ризотто по-милански с шафраном, окрашивающим блюдо в золотистый цвет.","fact":"Для ризотто используют особые сорта круглозёрного риса, например арборио, которые выделяют крахмал и дают кремовую текстуру.","wiki_en":"Risotto"},{"name":"Равиоли","emoji":"🥟","meta":["итальянская кухня","основное блюдо"],"description":"Небольшие квадратные или круглые изделия из тонкого теста с начинкой из мяса, сыра или овощей, которые варят и подают с соусом. Похожи на пельмени, но считаются типично итальянским блюдом со своей историей, уходящей в Средневековье.","fact":"Начинку для равиоли раньше часто делали из остатков вчерашнего мяса, чтобы не выбрасывать еду.","wiki_en":"Ravioli"},{"name":"Ньокки","emoji":"🥔","meta":["итальянская кухня","основное блюдо"],"description":"Небольшие клёцки, чаще всего из картофеля, муки и яйца, которые отваривают и подают с маслом, томатным соусом или песто. Похожие блюда из теста существовали в Европе задолго до появления картофеля в итальянской кухне.","fact":"В Риме ньокки традиционно едят по четвергам — этот обычай сохраняется в некоторых тратториях до сих пор.","wiki_en":"Gnocchi"},{"name":"Брускетта","emoji":"🍞","meta":["итальянская кухня","закуска"],"description":"Поджаренный ломоть хлеба, натёртый чесноком и сбрызнутый оливковым маслом, на который выкладывают начинку — чаще всего помидоры с базиликом. Простая закуска родом из Центральной Италии, ставшая популярной во всём мире.","fact":"Само название происходит от итальянского глагола bruscare — «жарить на углях».","wiki_en":"Bruschetta"},{"name":"Капрезе","emoji":"🍅","meta":["итальянская кухня","закуска"],"description":"Салат из ломтиков помидоров, моцареллы и листьев базилика, заправленный оливковым маслом. Цвета блюда — красный, белый и зелёный — повторяют флаг Италии, откуда и происходит рецепт с острова Капри.","fact":"Салат традиционно подают без уксуса и лишних добавок — вкус строится только на качестве самих продуктов.","wiki_en":"Caprese salad"},{"name":"Минестроне","emoji":"🍲","meta":["итальянская кухня","суп"],"description":"Густой овощной суп с добавлением бобовых, пасты или риса, рецепт которого сильно различается в зависимости от региона и сезона. Название происходит от слова «минестра» — суп, и отражает саму суть блюда как способа использовать то, что есть под рукой.","fact":"Единого рецепта минестроне не существует — практически в каждой итальянской семье готовят его по-своему.","wiki_en":"Minestrone"},{"name":"Тирамису","emoji":"🍰","meta":["итальянская кухня","десерт"],"description":"Десерт из слоёв печенья савоярди, пропитанного кофе, и крема на основе маскарпоне, присыпанный какао. Название переводится как «подними меня», намекая на бодрящий эффект кофе и какао в составе.","fact":"Считается, что тирамису придумали в регионе Венето только во второй половине XX века — для десерта это довольно молодое блюдо.","wiki_en":"Tiramisu"},{"name":"Панна-котта","emoji":"🍮","meta":["итальянская кухня","десерт"],"description":"Нежный десерт из сливок, сахара и желатина, который застывает в форме и подаётся с ягодным или карамельным соусом. Название переводится как «варёные сливки», хотя саму смесь лишь слегка нагревают, не доводя до кипения.","fact":"По распространённой версии, панна-котта родом из Пьемонта, а до появления желатина сливки загущали рыбьим клеем.","wiki_en":"Panna cotta"},{"name":"Джелато","emoji":"🍨","meta":["итальянская кухня","десерт"],"description":"Итальянское мороженое, которое содержит меньше воздуха и жира, чем обычное, за счёт чего получается более плотным и насыщенным по вкусу. Подают его чуть менее замороженным, что делает текстуру особенно мягкой.","fact":"Джелато обычно готовят и хранят при более высокой температуре, чем классическое мороженое, — это влияет на его текстуру.","wiki_en":"Gelato"},{"name":"Канноли","emoji":"🥐","meta":["итальянская кухня","десерт"],"description":"Хрустящие трубочки из жареного теста с начинкой из сладкого сыра рикотта, часто с цукатами или шоколадной крошкой. Десерт родом с Сицилии, ставший известным во всём мире во многом благодаря итальянской диаспоре в США.","fact":"В фильме «Крёстный отец» фраза про канноли стала одной из самых узнаваемых цитат о сицилийской кухне.","wiki_en":"Cannoli"},{"name":"Карпаччо","emoji":"🥩","meta":["итальянская кухня","закуска"],"description":"Тонко нарезанное сырое мясо или рыба, сбрызнутые оливковым маслом и лимонным соком, часто с добавлением пармезана и рукколы. Блюдо придумали в Венеции в середине XX века и назвали в честь художника, любившего красно-белые оттенки.","fact":"Название блюдо получило из-за сходства цвета сырой говядины с полотнами художника Витторе Карпаччо.","wiki_en":"Carpaccio"},{"name":"Рамен","emoji":"🍜","meta":["японская кухня","суп"],"description":"Суп с пшеничной лапшой в насыщенном бульоне на основе мяса, рыбы или мисо, с добавлением яйца, мяса и овощей. Блюдо пришло в Японию из Китая, но за десятилетия обросло множеством региональных вариаций и стало отдельной культурой.","fact":"В Японии существуют целые музеи, посвящённые истории рамена, а у каждого региона есть свой фирменный вариант бульона.","wiki_en":"Ramen"},{"name":"Удон","emoji":"🍜","meta":["японская кухня","основное блюдо"],"description":"Толстая пшеничная лапша, которую подают в горячем бульоне или холодной с соусом для макания. Одна из старейших разновидностей лапши в Японии, особенно популярная в регионе Сануки на острове Сикоку.","fact":"Толщина и мягкая текстура удона делают его одним из самых узнаваемых видов японской лапши на ощупь и на вкус.","wiki_en":"Udon"},{"name":"Мисо-суп","emoji":"🍵","meta":["японская кухня","суп"],"description":"Лёгкий суп на основе бульона даси с добавлением пасты мисо, тофу и водорослей вакаме. Один из главных элементов традиционного японского завтрака и обеда, который подают почти к каждому блюду.","fact":"Паста мисо получается путём ферментации соевых бобов, и процесс её выдержки может занимать от нескольких месяцев до нескольких лет.","wiki_en":"Miso soup"},{"name":"Темпура","emoji":"🍤","meta":["японская кухня","основное блюдо"],"description":"Морепродукты и овощи в лёгком кляре, обжаренные во фритюре до тонкой хрустящей корочки. Технику жарки в кляре в Японию привезли португальские миссионеры ещё в XVI веке, и с тех пор она стала частью национальной кухни.","fact":"Секрет лёгкости темпуры — в ледяной воде для теста и минимальном его перемешивании, чтобы не образовался глютен.","wiki_en":"Tempura"},{"name":"Якитори","emoji":"🍢","meta":["японская кухня","основное блюдо"],"description":"Кусочки курицы, нанизанные на бамбуковые шпажки и обжаренные на углях, часто с соусом на основе соевого соуса и мирина. Название дословно означает «жареная птица», а готовят якитори буквально из всех частей курицы.","fact":"В традиционных заведениях якитори в дело идёт практически вся курица, включая хрящи и кожу, чтобы не оставалось отходов.","wiki_en":"Yakitori"},{"name":"Онигири","emoji":"🍙","meta":["японская кухня","закуска"],"description":"Треугольные или круглые рисовые колобки, часто обёрнутые полоской водорослей нори, с начинкой внутри — рыбой, сливой или водорослями. Удобная еда навынос, которую в Японии продают практически на каждом углу.","fact":"Онигири готовили в Японии ещё несколько веков назад как удобную еду для путешественников и воинов, которую легко брать с собой.","wiki_en":"Onigiri"},{"name":"Гёдза","emoji":"🥟","meta":["японская кухня","закуска"],"description":"Жареные или приготовленные на пару пельмени с начинкой из мясного фарша и капусты, часто с чесноком и имбирём. Блюдо пришло в Японию из Китая и адаптировалось под местные вкусы, получив более тонкое тесто и хрустящее дно.","fact":"Классическую гёдзу жарят так, чтобы одна сторона стала хрустящей, а тесто наверху осталось мягким после пропаривания.","wiki_en":"Jiaozi"},{"name":"Такояки","emoji":"🐙","meta":["японская кухня","закуска"],"description":"Круглые шарики из жидкого теста с кусочками осьминога, которые обжаривают в специальной форме с полусферическими ячейками. Уличная закуска из Осаки, которую подают горячей, поливая соусом, майонезом и посыпая хлопьями бонито.","fact":"Название блюда происходит от слова «тако» — осьминог, который остаётся его обязательным ингредиентом.","wiki_en":"Takoyaki"},{"name":"Сашими","emoji":"🐟","meta":["японская кухня","закуска"],"description":"Тонко нарезанные ломтики сырой рыбы или морепродуктов, которые подают без риса, в отличие от суши, обычно с соевым соусом и васаби. Ключевую роль здесь играет исключительная свежесть продукта и мастерство нарезки.","fact":"Японское название блюда дословно переводится как «пронзённое тело» и связано со способом разделки рыбы.","wiki_en":"Sashimi"},{"name":"Ролл «Калифорния»","emoji":"🍣","meta":["японская кухня","основное блюдо"],"description":"Суши-ролл с рисом снаружи, начинённый крабовым мясом, авокадо и огурцом, который обычно посыпают икрой тобико. Придумали его не в Японии, а в США — как более привычный для западного вкуса вариант суши без сырой рыбы.","fact":"Ролл «Калифорния» считается одним из первых суши-роллов, созданных специально для западной аудитории.","wiki_en":"California roll"},{"name":"Ролл «Филадельфия»","emoji":"🍣","meta":["японская кухня","основное блюдо"],"description":"Суши-ролл с лососем, сливочным сыром и огурцом, названный в честь американского бренда сливочного сыра «Филадельфия». Ещё один пример адаптации японской кухни под западные вкусы, придуманный за пределами Японии.","fact":"Несмотря на японское оформление, ролл «Филадельфия» — изобретение американских суши-баров конца XX века.","wiki_en":"Philadelphia roll"},{"name":"Поке","emoji":"🥗","meta":["гавайская кухня","основное блюдо"],"description":"Гавайское блюдо из кубиков сырой рыбы, чаще всего тунца, замаринованной в соевом соусе с добавлением риса и овощей. Изначально простое рыбацкое блюдо превратилось в популярный во всём мире формат боула с морепродуктами.","fact":"Слово «поке» на гавайском означает «резать на кусочки» — именно так готовят рыбу для этого блюда.","wiki_en":"Poke (dish)"},{"name":"Тако","emoji":"🌮","meta":["мексиканская кухня","основное блюдо"],"description":"Кукурузная или пшеничная лепёшка, сложенная пополам и наполненная мясом, овощами и соусами. Одно из самых известных блюд мексиканской уличной еды, которое существует в десятках региональных вариаций.","fact":"Тако аль пастор жарят на вертикальном вертеле — этот способ принесли в Мексику иммигранты с Ближнего Востока.","wiki_en":"Taco"},{"name":"Буррито","emoji":"🌯","meta":["мексиканская кухня","основное блюдо"],"description":"Большая пшеничная лепёшка, в которую заворачивают начинку из мяса, риса, бобов и овощей в виде плотного рулета. Несмотря на мексиканское происхождение, современный формат буррито во многом сформировался уже в США.","fact":"Само слово «буррито» переводится как «маленький ослик» — возможно, из-за сходства свёрнутой лепёшки с поклажей на спине животного.","wiki_en":"Burrito"},{"name":"Кесадилья","emoji":"🫓","meta":["мексиканская кухня","основное блюдо"],"description":"Лепёшка тортилья с начинкой из сыра, которую складывают пополам и обжаривают до румяной корочки и расплавленного сыра внутри. В начинку часто добавляют мясо, овощи или грибы, а подают с гуакамоле или сметаной.","fact":"Классическая кесадилья строится вокруг плавленого сыра — именно от него происходит название блюда, от испанского queso.","wiki_en":"Quesadilla"},{"name":"Начос","emoji":"🧀","meta":["мексиканская кухня","закуска"],"description":"Хрустящие кукурузные чипсы, щедро политые расплавленным сыром и часто дополненные мясом, овощами и соусами. Придумали блюдо в приграничном мексиканском городе в середине XX века, назвав его в честь автора рецепта.","fact":"Блюдо получило имя в честь повара по прозвищу Начо, который придумал его для группы посетителей в 1940-х годах.","wiki_en":"Nachos"},{"name":"Гуакамоле","emoji":"🥑","meta":["мексиканская кухня","закуска"],"description":"Соус или паста из размятого авокадо с луком, лаймом, кинзой и перцем чили, который подают с чипсами или как дополнение к другим блюдам. Рецепт восходит ещё к ацтекам, задолго до прихода европейцев в Мексику.","fact":"Название происходит от науатльского слова ahuacamolli, что буквально означает «соус из авокадо».","wiki_en":"Guacamole"},{"name":"Фахитас","emoji":"🌯","meta":["мексиканская кухня","основное блюдо"],"description":"Обжаренные полоски мяса с луком и болгарским перцем, которые подают горячими на сковороде вместе с тёплыми тортильями для самостоятельной сборки. Блюдо родом из мексиканско-техасской пограничной кухни Tex-Mex.","fact":"Изначально фахитас готовили из недорогого отруба говядины — юбки, что и дало блюду название от испанского faja.","wiki_en":"Fajita"},{"name":"Чили кон карне","emoji":"🌶️","meta":["техасская кухня","основное блюдо"],"description":"Густое рагу из говяжьего фарша, фасоли, томатов и острого перца чили, которое медленно тушится до насыщенного вкуса. Несмотря на мексиканские корни названия, блюдо в его современном виде сформировалось в Техасе.","fact":"В самом Техасе существуют официальные соревнования по приготовлению чили кон карне с многолетней историей.","wiki_en":"Chili con carne"},{"name":"Чуррос","emoji":"🥖","meta":["испанская кухня","десерт"],"description":"Жареные во фритюре полоски теста с рифлёной поверхностью, обсыпанные сахаром и часто подаваемые с горячим шоколадом для макания. Популярны в Испании и Латинской Америке как уличная еда и завтрак.","fact":"По одной из версий, форма чуррос повторяет рога горных баранов, которых пасли испанские пастухи.","wiki_en":"Churro"},{"name":"Пад-тай","emoji":"🍜","meta":["тайская кухня","основное блюдо"],"description":"Жареная рисовая лапша с яйцом, соевым и рыбным соусом, часто с креветками или курицей, арахисом и ростками бобов. Блюдо активно продвигалось правительством Таиланда в середине XX века как символ национальной кухни.","fact":"Пад-тай распространяли в рамках государственной кампании, которая среди прочего приучала тайцев есть больше лапши и меньше риса.","wiki_en":"Pad thai"},{"name":"Том-ям","emoji":"🍤","meta":["тайская кухня","суп"],"description":"Острый и кислый тайский суп на основе бульона с лемонграссом, галангалом, листьями кафир-лайма и перцем чили, чаще всего с креветками. Один из самых узнаваемых символов тайской кухни за пределами страны.","fact":"Название происходит от двух тайских слов — «том», означающего варку, и «ям», обозначающего острый кисло-пряный салат.","wiki_en":"Tom yum"},{"name":"Том-кха","emoji":"🥥","meta":["тайская кухня","суп"],"description":"Тайский суп на основе кокосового молока с курицей, галангалом, лемонграссом и грибами, более мягкий и сливочный по вкусу, чем том-ям. Кокосовое молоко смягчает остроту специй, делая суп нежным, но при этом ароматным.","fact":"Несмотря на схожий набор специй с том-ямом, том-кха обязана своим характерным вкусом именно кокосовому молоку.","wiki_en":"Tom kha kai"},{"name":"Фо-бо","emoji":"🍜","meta":["вьетнамская кухня","суп"],"description":"Вьетнамский суп с рисовой лапшой в ароматном бульоне на основе говяжьих костей, звёздчатого аниса и корицы, с ломтиками мяса и свежей зеленью. Одно из главных блюд вьетнамской кухни, которое едят на завтрак, обед и ужин.","fact":"Название «фо» может происходить от французского блюда pot-au-feu, повлиявшего на кухню Вьетнама в колониальный период.","wiki_en":"Pho"},{"name":"Спринг-роллы","emoji":"🥢","meta":["вьетнамская кухня","закуска"],"description":"Тонкие рисовые блины, в которые заворачивают овощи, зелень, рисовую лапшу и иногда креветки или мясо. Подают как в свежем виде с соусом для макания, так и обжаренными до хрустящей корочки.","fact":"Свежие вьетнамские спринг-роллы, в отличие от жареных, вообще не требуют термической обработки после сборки.","wiki_en":"Spring roll"},{"name":"Бань-ми","emoji":"🥖","meta":["вьетнамская кухня","основное блюдо"],"description":"Вьетнамский сэндвич на основе хрустящего багета с паштетом, маринованными овощами, свежей зеленью и мясом. Сочетает французское наследие колониального периода с традиционными вьетнамскими вкусами и специями.","fact":"Хрустящий тонкий багет для бань-ми — прямое наследие французской колонизации Вьетнама.","wiki_en":"Bánh mì"},{"name":"Наси-горенг","emoji":"🍚","meta":["индонезийская кухня","основное блюдо"],"description":"Жареный рис с соевым соусом, овощами, яйцом и мясом или креветками, часто украшенный жареным луком и подаваемый с чипсами из крекера. Одно из самых популярных блюд Индонезии, которое готовят практически в каждом доме.","fact":"Название дословно переводится как «жареный рис», а рецепт в каждой семье и регионе Индонезии отличается.","wiki_en":"Nasi goreng"},{"name":"Сатай","emoji":"🍢","meta":["индонезийская кухня","основное блюдо"],"description":"Маринованные кусочки мяса на шпажках, обжаренные на углях и поданные с густым соусом из жареного арахиса. Блюдо распространено по всей Юго-Восточной Азии, а особенно популярно в Индонезии и Малайзии.","fact":"Арахисовый соус к сатаю готовят с добавлением специй и лемонграсса, из-за чего он получается насыщенным и сладковато-острым.","wiki_en":"Satay"},{"name":"Лакса","emoji":"🍜","meta":["юго-восточноазиатская кухня","суп"],"description":"Острый суп с лапшой на основе кокосового молока или кислого бульона, распространённый в Малайзии и Сингапуре. Сочетает китайские и малайские кулинарные традиции — именно поэтому его называют блюдом-символом культуры перанакан.","fact":"Существует множество региональных версий лаксы, которые могут заметно отличаться по цвету, остроте и составу бульона.","wiki_en":"Laksa"},{"name":"Димсамы","emoji":"🥟","meta":["китайская кухня","закуска"],"description":"Небольшие порционные блюда — пельмени, булочки и рулетики на пару, которые подают в маленьких корзинках во время традиционной китайской чайной трапезы. Появились в кантонской кухне и стали основой ритуала под названием «ямча».","fact":"Традиция есть димсамы тесно связана с чаепитием — сам термин «ямча» дословно означает «пить чай».","wiki_en":"Dim sum"},{"name":"Утка по-пекински","emoji":"🦆","meta":["китайская кухня","основное блюдо"],"description":"Утка с хрустящей карамелизованной кожей, которую запекают особым способом и подают тонко нарезанной с блинчиками, зелёным луком и соусом хойсин. Одно из самых знаменитых блюд китайской кухни с многовековой историей.","fact":"Для получения хрустящей кожи утку перед запеканием обдают кипятком и сушат на воздухе, иногда до суток.","wiki_en":"Peking duck"},{"name":"Курица гунбао","emoji":"🌶️","meta":["китайская кухня","основное блюдо"],"description":"Обжаренные кусочки курицы с арахисом, сушёным перцем чили и овощами в остро-сладком соусе. Блюдо родом из провинции Сычуань, а его название связано с титулом чиновника, при дворе которого его якобы впервые подали.","fact":"Название блюда происходит от почётного титула «гунбао», который в XIX веке носил один из сычуаньских губернаторов.","wiki_en":"Kung Pao chicken"},{"name":"Жареный рис","emoji":"🍚","meta":["китайская кухня","основное блюдо"],"description":"Рис, обжаренный на сильном огне с яйцом, овощами и часто с мясом или креветками, обычно готовится из уже остывшего варёного риса. Одно из самых распространённых блюд китайской кухни, у которого есть десятки региональных версий.","fact":"Считается, что именно вчерашний подсохший рис даёт лучший результат при жарке — свежесваренный слишком влажный и слипается.","wiki_en":"Fried rice"},{"name":"Вонтоны","emoji":"🥟","meta":["китайская кухня","суп"],"description":"Тонкие пельмени из теста с начинкой из мясного фарша или креветок, которые подают в бульоне или обжаренными. Тесто для вонтонов раскатывают особенно тонко, из-за чего они отличаются от более плотных китайских пельменей цзяоцзы.","fact":"В англоязычных странах суп с вонтонами стал одним из самых узнаваемых блюд китайских ресторанов.","wiki_en":"Wonton"},{"name":"Баоцзы","emoji":"🥟","meta":["китайская кухня","закуска"],"description":"Пышные паровые булочки из дрожжевого теста с начинкой из мяса, овощей или сладкой пасты. Едят их руками, часто на завтрак или в качестве перекуса, а готовят на пару в бамбуковых корзинках.","fact":"Мягкое пышное тесто баоцзы получается благодаря дрожжевой закваске и долгому времени расстойки перед варкой на пару.","wiki_en":"Baozi"},{"name":"Кимчи","emoji":"🌶️","meta":["корейская кухня","закуска"],"description":"Ферментированные овощи, чаще всего пекинская капуста, приправленные красным перцем, чесноком и имбирём. Один из главных символов корейской кухни, который подают практически к каждому приёму пищи.","fact":"В Южной Корее существуют специальные холодильники, предназначенные исключительно для хранения и ферментации кимчи.","wiki_en":"Kimchi"},{"name":"Бибимбап","emoji":"🍚","meta":["корейская кухня","основное блюдо"],"description":"Рис, смешанный с разными овощами, мясом, яйцом и острой пастой кочхуджан, который подают в одной миске и перемешивают перед едой. Название дословно означает «смешанный рис», а само блюдо славится ярким набором цветов и вкусов.","fact":"Горячий вариант блюда подают в раскалённой каменной посуде, из-за чего рис снизу становится хрустящим.","wiki_en":"Bibimbap"},{"name":"Токпокки","emoji":"🌶️","meta":["корейская кухня","закуска"],"description":"Цилиндрические рисовые клёцки, тушённые в остро-сладком соусе на основе перечной пасты кочхуджан. Одно из самых популярных уличных блюд Южной Кореи, особенно любимое у школьников и студентов.","fact":"Токпокки часто продают на уличных лотках вместе с рыбными шариками и варёными яйцами, добавляемыми прямо в соус.","wiki_en":"Tteokbokki"},{"name":"Курица тикка-масала","emoji":"🍛","meta":["индийская кухня","основное блюдо"],"description":"Кусочки курицы, замаринованные в специях и йогурте, запечённые и поданные в густом сливочно-томатном соусе с пряностями. Хотя блюдо ассоциируется с Индией, значительную роль в его появлении сыграла индийская диаспора в Великобритании.","fact":"Некоторые историки кулинарии считают, что современный рецепт тикка-масала был придуман индийскими поварами именно в Британии.","wiki_en":"Chicken tikka masala"},{"name":"Баттер чикен","emoji":"🍛","meta":["индийская кухня","основное блюдо"],"description":"Кусочки курицы в мягком сливочном соусе на основе томатов, сливочного масла и пряностей, менее острые, чем многие другие индийские карри. Блюдо придумали в Дели в середине XX века как способ использовать остатки курицы тандури.","fact":"По легенде, соус для баттер чикен придумали, чтобы курица тандури не пересыхала — остатки мяса смешали с томатно-масляной подливой.","wiki_en":"Butter chicken"},{"name":"Бирьяни","emoji":"🍛","meta":["индийская кухня","основное блюдо"],"description":"Слоёное блюдо из длиннозёрного риса басмати, мяса или овощей и смеси пряностей, которое готовят методом томления в закрытом казане. Существует множество региональных вариаций по всей Индии и Пакистану, каждая со своим набором специй.","fact":"Рис и мясо для бирьяни часто готовят отдельно, а затем соединяют слоями и доводят до готовности на пару в закрытой посуде.","wiki_en":"Biryani"},{"name":"Наан","emoji":"🫓","meta":["индийская кухня","хлеб"],"description":"Мягкая пшеничная лепёшка на дрожжевом тесте, которую традиционно выпекают на стенках глиняной печи тандыр. Подают горячей как дополнение к карри и другим индийским блюдам, часто с маслом или чесноком.","fact":"Слепленную лепёшку прижимают прямо к раскалённой внутренней стенке тандыра, где она печётся за считаные минуты.","wiki_en":"Naan"},{"name":"Самоса","emoji":"🥟","meta":["индийская кухня","закуска"],"description":"Треугольные пирожки из тонкого теста с начинкой из картофеля, гороха и специй, обжаренные во фритюре до хрустящей корочки. Популярны по всей Южной Азии и на Ближнем Востоке как уличная закуска и перекус к чаю.","fact":"Считается, что прообраз самосы попал в Индию через персидских и центральноазиатских торговцев ещё в Средние века.","wiki_en":"Samosa"},{"name":"Карри","emoji":"🍛","meta":["индийская кухня","основное блюдо"],"description":"Общее название для блюд с густым пряным соусом на основе специй, которые готовят с мясом, рыбой или овощами. Рецепты и наборы пряностей сильно различаются от региона к региону — единого «карри» в Индии не существует.","fact":"Слово «карри» пришло в английский язык из тамильского слова «кари», означающего соус или подливу.","wiki_en":"Curry"},{"name":"Борщ","emoji":"🍲","meta":["украинская кухня","суп"],"description":"Наваристый суп на основе свёклы, придающей блюду насыщенный красный цвет, с капустой, картофелем и мясом. Распространён по всей Восточной Европе, а подают его традиционно со сметаной и чесночными пампушками.","fact":"В 2022 году ЮНЕСКО включила культуру приготовления украинского борща в список нематериального наследия, нуждающегося в срочной охране.","wiki_en":"Borscht"},{"name":"Пельмени","emoji":"🥟","meta":["русская кухня","основное блюдо"],"description":"Небольшие изделия из тонкого пресного теста с начинкой из мясного фарша, которые отваривают в кипящей воде или бульоне. Считаются одним из главных символов русской кухни, хотя похожие блюда есть у многих народов Евразии.","fact":"В Сибири пельмени традиционно лепили большими партиями и замораживали на морозе впрок на всю зиму.","wiki_en":"Pelmeni"},{"name":"Блины","emoji":"🥞","meta":["русская кухня","основное блюдо"],"description":"Тонкие лепёшки из жидкого теста, обжаренные на сковороде и поданные со сметаной, маслом, икрой или сладкой начинкой. Одно из старейших блюд русской кухни, тесно связанное с масленичными традициями и встречей весны.","fact":"На Масленицу круглый румяный блин традиционно символизировал солнце и проводы зимы.","wiki_en":"Blini"},{"name":"Салат оливье","emoji":"🥗","meta":["русская кухня","закуска"],"description":"Салат из варёных овощей, мяса или колбасы, яиц и маринованных огурцов, заправленный майонезом. Придумал его в XIX веке повар французского происхождения, но современная версия сильно отличается от оригинального рецепта.","fact":"Считается, что оригинальный рецепт повара Люсьена Оливье включал рябчиков и раковые шейки и держался в секрете.","wiki_en":"Olivier salad"},{"name":"Селёдка под шубой","emoji":"🐟","meta":["русская кухня","закуска"],"description":"Слоёный салат из кусочков солёной сельди, картофеля, моркови и свёклы под майонезом, названный за яркий «шубный» вид верхнего слоя. Традиционное блюдо новогоднего и праздничного стола на постсоветском пространстве.","fact":"Популярная версия, что «шуба» — это аббревиатура революционного лозунга, придумана уже в наши дни: слой свёклы просто напоминает шубу.","wiki_en":"Dressed herring"},{"name":"Винегрет","emoji":"🥗","meta":["русская кухня","закуска"],"description":"Салат из отварной свёклы, моркови и картофеля с солёными огурцами и квашеной капустой, заправленный растительным маслом. Название происходит от французского соуса винегрет, хотя само блюдо сформировалось именно в русской кухне.","fact":"От французской кухни в винегрете осталось, по сути, только название заправки — сам салат сложился в русской кухне.","wiki_en":"Vinegret"},{"name":"Щи","emoji":"🍲","meta":["русская кухня","суп"],"description":"Суп на основе свежей или квашеной капусты с мясом или грибами, один из старейших и наиболее почитаемых супов русской кухни. Зимой густые щи нередко замораживали и брали с собой в дорогу, отрубая по куску и разогревая на привале.","fact":"На Руси существовала поговорка «щи да каша — пища наша», отражающая центральное место этого супа в рационе.","wiki_en":"Shchi"},{"name":"Окрошка","emoji":"🥒","meta":["русская кухня","суп"],"description":"Холодный суп из мелко нарезанных овощей, варёного мяса и яиц, залитых квасом, кефиром или сывороткой. Традиционно готовят и едят летом как освежающее блюдо в жаркую погоду.","fact":"Классическую окрошку готовят именно на хлебном квасе, хотя сегодня всё чаще встречаются варианты на кефире.","wiki_en":"Okroshka"},{"name":"Солянка","emoji":"🍲","meta":["русская кухня","суп"],"description":"Густой наваристый суп на основе солёных огурцов, маслин и лимона с несколькими видами мяса, рыбы или колбасы. Отличается насыщенным кисло-солёно-острым вкусом благодаря рассолу и разнообразию входящих в него продуктов.","fact":"Существуют мясная, рыбная и грибная версии солянки, объединённые общим кисло-солёным характером бульона.","wiki_en":"Solyanka"},{"name":"Уха","emoji":"🐟","meta":["русская кухня","суп"],"description":"Прозрачный рыбный суп, который варят из одного или нескольких видов рыбы с минимальным набором овощей, чтобы не перебивать вкус рыбы. Одно из старейших блюд русской кухни, тесно связанное с рыболовными и походными традициями.","fact":"Для особой прозрачности бульона в уху иногда добавляли взбитый яичный белок, который собирал на себя муть.","wiki_en":"Ukha"},{"name":"Бефстроганов","emoji":"🥩","meta":["русская кухня","основное блюдо"],"description":"Тонко нарезанная говядина, обжаренная и потушённая в сметанном соусе, часто с добавлением горчицы и лука. Блюдо названо в честь графского рода Строгановых и с XIX века распространилось далеко за пределы России.","fact":"Блюдо получило имя в честь семьи Строгановых, при этом точная история его появления остаётся предметом споров.","wiki_en":"Beef Stroganoff"},{"name":"Котлета по-киевски","emoji":"🍗","meta":["украинская кухня","основное блюдо"],"description":"Отбивное куриное филе, завёрнутое вокруг кусочка сливочного масла и обжаренное в панировке до золотистой корочки. При разрезании из котлеты вытекает горячее масло, что делает подачу этого блюда особенно эффектной.","fact":"Несмотря на название, у блюда есть версии происхождения, связывающие его не только с Киевом, но и с французской кулинарной традицией.","wiki_en":"Chicken Kiev"},{"name":"Холодец","emoji":"🍖","meta":["русская кухня","закуска"],"description":"Застывший мясной бульон с кусочками мяса, который варят долгое время, пока кости и хрящи не отдадут достаточно желатина для естественного застывания. Традиционно подают холодным, часто с хреном или горчицей, особенно на праздничный стол.","fact":"Для застывания холодца без добавления желатина бульон варят особенно долго, используя части туши, богатые коллагеном.","wiki_en":"Kholodets"},{"name":"Пирожки","emoji":"🥟","meta":["русская кухня","закуска"],"description":"Небольшие изделия из дрожжевого или пресного теста с самой разной начинкой — от картофеля и капусты до мяса и ягод, которые жарят или запекают. Универсальная домашняя выпечка, распространённая по всей Восточной Европе.","fact":"Форма и способ приготовления пирожков — жареные или печёные — традиционно различаются в зависимости от региона и семьи.","wiki_en":"Pirozhki"},{"name":"Сырники","emoji":"🧀","meta":["русская кухня","основное блюдо"],"description":"Небольшие обжаренные лепёшки из творога, яиц и муки, которые подают на завтрак со сметаной, вареньем или мёдом. Несмотря на название, готовят их не из сыра, а из творога, который в некоторых славянских языках так и называют.","fact":"Название блюда объясняется тем, что в некоторых восточнославянских языках творог исторически называли «сыром».","wiki_en":"Syrniki"},{"name":"Вареники","emoji":"🥟","meta":["украинская кухня","основное блюдо"],"description":"Изделия из пресного теста с начинкой из картофеля, творога, вишни или капусты, которые отваривают в подсоленной воде. Один из главных символов украинской кухни, известный также во многих других странах Восточной Европы.","fact":"Ближайшие родственники вареников — польские пероги: и те и другие лепят из пресного теста в форме полумесяца.","wiki_en":"Varenyky"},{"name":"Голубцы","emoji":"🥬","meta":["украинская кухня","основное блюдо"],"description":"Капустные листья, свёрнутые в рулет с начинкой из мясного фарша и риса, которые тушат в томатном или сметанном соусе. Блюдо распространено по всей Восточной Европе и на Балканах, хотя рецептура и подача заметно различаются.","fact":"Техника приготовления голубцов близка к долме — блюду из начинённых виноградных листьев, известному на Балканах и Ближнем Востоке.","wiki_en":"Golubtsy"},{"name":"Драники","emoji":"🥔","meta":["белорусская кухня","основное блюдо"],"description":"Оладьи из тёртого сырого картофеля, обжаренные на сковороде до хрустящей корочки, часто подают со сметаной. Одно из главных блюд белорусской кухни, известное также в Польше, Литве и на Украине под другими названиями.","fact":"Похожие картофельные оладьи есть у многих европейских кухонь, включая еврейские латкес и немецкие Kartoffelpuffer.","wiki_en":"Draniki"},{"name":"Медовик","emoji":"🍯","meta":["русская кухня","десерт"],"description":"Многослойный торт из тонких медовых коржей, промазанных сметанным или заварным кремом, который перед подачей выдерживают, чтобы коржи размягчились. По легенде, торт придумали для российской императрицы, не любившей запах мёда.","fact":"В тесто для коржей мёд добавляют вместе с содой: от этой реакции оно светлеет, поднимается и приобретает карамельный оттенок.","wiki_en":"Medovik"},{"name":"Торт «Наполеон»","emoji":"🍰","meta":["русская кухня","десерт"],"description":"Многослойный торт из хрустящих коржей слоёного теста, промазанных заварным кремом, популярный на всём постсоветском пространстве. Название связано с французским слоёным пирогом, хотя современный рецепт сложился уже в России.","fact":"Название торта в России связывают со столетием победы над Наполеоном, хотя прямой связи с самим императором у рецепта нет.","wiki_en":"Mille-feuille"},{"name":"Шашлык","emoji":"🍢","meta":["кавказская кухня","основное блюдо"],"description":"Кусочки маринованного мяса, нанизанные на шампуры и обжаренные на углях мангала. Блюдо особенно популярно на Кавказе и в России, где его готовят на пикниках и праздниках почти круглый год.","fact":"Слово «шашлык» пришло в русский язык из крымскотатарского и связано со словом «шиш» — вертел.","wiki_en":"Shashlik"},{"name":"Плов","emoji":"🍚","meta":["среднеазиатская кухня","основное блюдо"],"description":"Блюдо из риса, мяса, моркови и лука, которые готовят вместе в казане так, чтобы рис пропитался жиром и соками мяса. Существует множество региональных вариаций плова в странах Средней Азии, на Кавказе и Ближнем Востоке.","fact":"В Узбекистане плов часто готовят как главное блюдо больших праздников, а рецепты и техника заметно различаются по городам.","wiki_en":"Pilaf"},{"name":"Манты","emoji":"🥟","meta":["среднеазиатская кухня","основное блюдо"],"description":"Крупные изделия из тонкого теста с начинкой из рубленого мяса и лука, которые готовят на пару в специальной многоярусной кастрюле мантоварке. Распространены по всей Средней Азии, Кавказу и Турции под похожими названиями.","fact":"Классическую начинку для мантов рубят ножом, а не пропускают через мясорубку, чтобы сохранить сочность мяса.","wiki_en":"Manti (food)"},{"name":"Лагман","emoji":"🍜","meta":["среднеазиатская кухня","суп"],"description":"Блюдо из длинной вытянутой вручную лапши с наваристой мясной подливой с овощами, которое может подаваться как суп или как более густое второе блюдо. Популярно у уйгуров и по всей Средней Азии.","fact":"Технику вытягивания теста для лагмана вручную до тонких длинных нитей мастера оттачивают годами.","wiki_en":"Laghman (food)"},{"name":"Самса","emoji":"🥟","meta":["среднеазиатская кухня","закуска"],"description":"Слоёные пирожки с начинкой из мяса, лука и специй, которые традиционно выпекают на стенках тандыра до румяной хрустящей корочки. Популярны по всей Средней Азии, где их часто продают как уличную еду.","fact":"Название и происхождение самсы связывают с той же кулинарной традицией, что и индийскую самосу.","wiki_en":"Samsa (food)"},{"name":"Бешбармак","emoji":"🍖","meta":["казахская кухня","основное блюдо"],"description":"Отварное мясо, чаще всего баранина или конина, поданное с широкой раскатанной лапшой и бульоном. Название дословно переводится как «пять пальцев» — блюдо традиционно едят руками.","fact":"Бешбармак считается главным праздничным блюдом у казахов и других тюркских народов Средней Азии.","wiki_en":"Beshbarmak"},{"name":"Чебуреки","emoji":"🥟","meta":["крымскотатарская кухня","закуска"],"description":"Тонкие изделия из пресного теста с начинкой из мясного фарша, которые обжаривают во фритюре до хрустящей пузырчатой корочки. Блюдо крымскотатарской кухни, широко распространившееся по всей России и Украине.","fact":"Правильно приготовленный чебурек должен слегка «стрелять» горячим соком при первом надкусывании.","wiki_en":"Chebureki"},{"name":"Хачапури","emoji":"🧀","meta":["грузинская кухня","основное блюдо"],"description":"Лепёшка из дрожжевого теста с начинкой из сыра, самая известная версия которой — лодочка по-аджарски с яйцом и маслом сверху. Одно из главных блюд грузинской кухни, у которого существует множество региональных форм.","fact":"В хачапури по-аджарски яйцо и масло принято размешивать прямо в горячем сыре, отрывая кусочки теста по краям.","wiki_en":"Khachapuri"},{"name":"Хинкали","emoji":"🥟","meta":["грузинская кухня","основное блюдо"],"description":"Крупные грузинские пельмени с сочной мясной начинкой и бульоном внутри. Их едят руками, держа за хвостик из теста, — сначала надкусывают и выпивают бульон, а сам хвостик обычно оставляют на тарелке.","fact":"По оставленным на тарелке хвостикам в Грузии принято считать, сколько хинкали съел каждый за столом.","wiki_en":"Khinkali"},{"name":"Харчо","emoji":"🍲","meta":["грузинская кухня","суп"],"description":"Острый грузинский суп из говядины с рисом, орехами и кислой добавкой — чаще всего сливой ткемали или гранатовым соком. Насыщенный вкус супу придаёт сочетание пряностей, включая хмели-сунели.","fact":"Для кислинки в Грузии часто берут тклапи — высушенное в тонкий лист сливовое пюре, которое разводят прямо в бульоне.","wiki_en":"Kharcho"},{"name":"Чахохбили","emoji":"🍗","meta":["грузинская кухня","основное блюдо"],"description":"Тушёная курица с большим количеством лука, помидоров и пряных трав, которую готовят без добавления масла и воды. Блюдо относится к традиционной грузинской домашней кухне и отличается насыщенным томатным вкусом.","fact":"Изначально чахохбили готовили из дичи, а куриное мясо стало основным ингредиентом уже позже.","wiki_en":"Chakhokhbili"},{"name":"Сациви","emoji":"🍗","meta":["грузинская кухня","основное блюдо"],"description":"Холодное блюдо из курицы или индейки в густом соусе из грецких орехов со специями, включая уцхо-сунели и шафран имеретинский. Традиционно подаётся на праздничный грузинский стол, часто на Новый год.","fact":"Соус для сациви готовят на основе молотых грецких орехов, без использования муки или крахмала для загустения.","wiki_en":"Satsivi"},{"name":"Лобио","emoji":"🫘","meta":["грузинская кухня","основное блюдо"],"description":"Блюдо из тушёной фасоли с луком, чесноком и пряными травами, которое может подаваться как горячим, так и холодным. Один из основных постных вариантов грузинской кухни, часто подаётся с кукурузным хлебом мчади.","fact":"У лобио есть десятки вариаций — от горячего тушёного до холодного, спрессованного в лепёшки с орехами.","wiki_en":"Lobio"},{"name":"Чурчхела","emoji":"🍇","meta":["грузинская кухня","десерт"],"description":"Нанизанные на нить орехи, обмакнутые несколько раз в загущённый виноградный сок и высушенные до плотной желейной консистенции. Традиционная грузинская сладость, которую готовят преимущественно во время сбора винограда.","fact":"Оболочку варят из виноградного сока с мукой, а орехи окунают в неё много раз, наращивая слой и просушивая между погружениями.","wiki_en":"Churchkhela"},{"name":"Долма","emoji":"🍇","meta":["ближневосточная кухня","основное блюдо"],"description":"Виноградные или капустные листья, свёрнутые в небольшие рулеты с начинкой из риса и часто мясного фарша с пряностями. Блюдо распространено на Кавказе, Балканах и Ближнем Востоке, где существует множество его вариаций.","fact":"Название «долма» происходит от турецкого слова, означающего «наполненный» или «фаршированный».","wiki_en":"Dolma"},{"name":"Шаурма","emoji":"🌯","meta":["ближневосточная кухня","основное блюдо"],"description":"Тонкая лепёшка с начинкой из тонко нарезанного жареного мяса, овощей и соуса, которую заворачивают в рулет. Блюдо основано на технике жарки мяса на вертикальном вертеле, распространённой по всему Ближнему Востоку.","fact":"Способ жарки мяса на вертикальном вертеле лёг в основу целого семейства похожих блюд — от турецкого дёнера до греческого гироса.","wiki_en":"Shawarma"},{"name":"Кебаб","emoji":"🍢","meta":["ближневосточная кухня","основное блюдо"],"description":"Общее название для блюд из жареного мяса, часто на шампурах или вертеле, распространённых по всему Ближнему Востоку, Кавказу и Центральной Азии. Конкретный рецепт и способ подачи сильно различаются от страны к стране.","fact":"Название знаменитого дёнер-кебаба означает «вращающийся кебаб» — по способу жарки мяса на крутящемся вертикальном вертеле.","wiki_en":"Kebab"},{"name":"Фалафель","emoji":"🧆","meta":["ближневосточная кухня","закуска"],"description":"Обжаренные во фритюре шарики из измельчённого нута или бобов с пряностями, часто подаются в лепёшке питта с овощами и соусом тахини. Популярное блюдо уличной еды на всём Ближнем Востоке.","fact":"Считается, что фалафель изначально готовили из бобов фава, а нутовая версия распространилась позже.","wiki_en":"Falafel"},{"name":"Хумус","emoji":"🫘","meta":["ближневосточная кухня","закуска"],"description":"Паста из отварного нута, тахини, чеснока, лимонного сока и оливкового масла, которую подают с лепёшками или овощами. Один из самых узнаваемых элементов ближневосточной кухни, ставший популярным блюдом по всему миру.","fact":"Слово «хумус» в арабском языке буквально означает «нут» — основной ингредиент этого блюда.","wiki_en":"Hummus"},{"name":"Табуле","emoji":"🥗","meta":["ближневосточная кухня","закуска"],"description":"Салат из мелкой крупы булгур с большим количеством петрушки, мяты, помидоров и заправкой из лимонного сока и оливкового масла. Родом из левантийской кухни, отличается свежим травяным вкусом за счёт обилия зелени.","fact":"В классическом табуле петрушки обычно больше, чем самой крупы булгур, — зелень здесь главный ингредиент.","wiki_en":"Tabbouleh"},{"name":"Шакшука","emoji":"🍳","meta":["ближневосточная кухня","основное блюдо"],"description":"Яйца, запечённые в густом соусе из тушёных томатов, лука и перца со специями, которые подают прямо на сковороде. Популярна на Ближнем Востоке и в Северной Африке, часто как сытный завтрак с хлебом для макания в соус.","fact":"Название «шакшука» связывают с арабским словом, означающим нечто «смешанное» — отсылка к способу приготовления соуса.","wiki_en":"Shakshouka"},{"name":"Кускус","emoji":"🍲","meta":["североафриканская кухня","основное блюдо"],"description":"Мелкая крупа из твёрдой пшеницы, которую готовят на пару, часто подают с тушёными овощами и мясом. Основа традиционной кухни стран Магриба — Марокко, Алжира и Туниса, где его готовят почти ежедневно.","fact":"В 2020 году ЮНЕСКО включила знания и навыки, связанные с приготовлением и подачей кускуса, в список нематериального наследия.","wiki_en":"Couscous"},{"name":"Тажин","emoji":"🍲","meta":["марокканская кухня","основное блюдо"],"description":"Тушёное мясо или овощи с сухофруктами и пряностями, которые медленно готовят в конусообразной глиняной посуде того же названия. Форма крышки позволяет пару конденсироваться и стекать обратно, сохраняя блюдо сочным.","fact":"Название блюда происходит от той самой глиняной посуды конической формы, в которой его готовят и подают.","wiki_en":"Tajine"},{"name":"Пахлава","emoji":"🍯","meta":["ближневосточная кухня","десерт"],"description":"Многослойный десерт из тончайшего теста фило с начинкой из молотых орехов, пропитанный сахарным или медовым сиропом. Распространена на Балканах, Ближнем Востоке и Кавказе, где существуют разные варианты нарезки и начинки.","fact":"На классическую пахлаву уходят десятки тончайших слоёв теста, раскатанных почти до прозрачности.","wiki_en":"Baklava"},{"name":"Паэлья","emoji":"🥘","meta":["испанская кухня","основное блюдо"],"description":"Блюдо из риса, приготовленного в широкой плоской сковороде с шафраном, овощами и морепродуктами или мясом. Родом из региона Валенсия, где традиционный рецепт включал кролика, курицу и фасоль, а не морепродукты.","fact":"Гурманы ценят в паэлье сокаррат — подрумяненный, чуть хрустящий слой риса, который образуется у самого дна сковороды.","wiki_en":"Paella"},{"name":"Гаспачо","emoji":"🍅","meta":["испанская кухня","суп"],"description":"Холодный суп-пюре из свежих помидоров, огурцов, перца и хлеба, заправленный оливковым маслом и уксусом. Традиционное летнее блюдо юга Испании, которое едят охлаждённым в жаркую погоду.","fact":"Ранние версии гаспачо готовили без томатов — этот овощ добавили в рецепт только после того, как он попал в Европу из Америки.","wiki_en":"Gazpacho"},{"name":"Хамон","emoji":"🥓","meta":["испанская кухня","закуска"],"description":"Вяленый свиной окорок, который выдерживают в течение долгого времени, добиваясь плотной текстуры и насыщенного вкуса. Подают его тонко нарезанным, часто как самостоятельную закуску или дополнение к другим блюдам.","fact":"Выдержка хамона высшего качества может занимать несколько лет — чем дольше срок, тем насыщеннее вкус мяса.","wiki_en":"Jamón"},{"name":"Испанская тортилья","emoji":"🍳","meta":["испанская кухня","основное блюдо"],"description":"Плотный омлет из яиц и обжаренного картофеля, часто с луком, который готовят на сковороде и переворачивают целиком. Одно из самых распространённых блюд домашней испанской кухни, которое подают как горячим, так и холодным.","fact":"Главный спор среди испанских поваров — стоит ли добавлять в тортилью лук, и единого мнения на этот счёт не существует.","wiki_en":"Spanish omelette"},{"name":"Пататас бравас","emoji":"🥔","meta":["испанская кухня","закуска"],"description":"Обжаренные кубики картофеля, поданные с острым томатным соусом и часто с чесночным майонезом айоли. Одна из самых популярных тапас в испанских барах, название которой переводится как «дерзкий картофель».","fact":"Название bravas связано именно с остротой соуса, которым поливают картофель, а не со способом его жарки.","wiki_en":"Patatas bravas"},{"name":"Круассан","emoji":"🥐","meta":["французская кухня","выпечка"],"description":"Слоёная выпечка в форме полумесяца из дрожжевого теста с большим количеством сливочного масла, которое даёт хрустящую и одновременно воздушную структуру. Стал одним из главных символов французского завтрака.","fact":"Форма полумесяца, по одной из версий, связана с австрийской выпечкой, которая легла в основу французского круассана.","wiki_en":"Croissant"},{"name":"Рататуй","emoji":"🍆","meta":["французская кухня","основное блюдо"],"description":"Тушёное овощное блюдо из баклажанов, цукини, перца и томатов с прованскими травами, родом из региона Прованс. Может готовиться как в виде простого рагу, так и в виде аккуратно выложенных тонких слоёв овощей.","fact":"Изысканная версия рататуя с тонко нарезанными и красиво выложенными овощами стала известна во многом благодаря одноимённому мультфильму.","wiki_en":"Ratatouille"},{"name":"Луковый суп","emoji":"🍲","meta":["французская кухня","суп"],"description":"Суп из долго карамелизованного лука на говяжьем или курином бульоне, который подают под шапкой из хлеба и расплавленного сыра. Одно из классических блюд французской кухни, особенно популярное в холодное время года.","fact":"Ключевая часть рецепта — долгая, иногда почти часовая карамелизация лука, придающая супу глубокий сладковатый вкус.","wiki_en":"French onion soup"},{"name":"Крем-брюле","emoji":"🍮","meta":["французская кухня","десерт"],"description":"Нежный заварной крем на основе сливок и яичных желтков, покрытый сверху тонкой хрустящей карамельной корочкой. Корочку традиционно формируют, посыпав крем сахаром и подпалив его горелкой прямо перед подачей.","fact":"Рецепт под названием крем-брюле встречается во французской кулинарной книге конца XVII века — десерту уже больше трёхсот лет.","wiki_en":"Crème brûlée"},{"name":"Киш-лорен","emoji":"🥧","meta":["французская кухня","основное блюдо"],"description":"Открытый пирог из песочного теста с начинкой из яично-сливочной заливки и обжаренной копчёной грудинки. Родом из региона Лотарингия на северо-востоке Франции, откуда и происходит название блюда.","fact":"Классический рецепт киш-лорен не включает лук — этот вариант считается более поздним дополнением к оригинальному блюду.","wiki_en":"Quiche Lorraine"},{"name":"Буйабес","emoji":"🐟","meta":["французская кухня","суп"],"description":"Наваристый рыбный суп из нескольких видов рыбы и морепродуктов с пряностями и шафраном, родом из портового Марселя. Традиционно подают с гренками и соусом руй, а бульон и рыбу иногда едят отдельно.","fact":"Изначально буйабес готовили рыбаки из непроданного улова — мелкой рыбы, которую было сложно продать на рынке.","wiki_en":"Bouillabaisse"},{"name":"Фуа-гра","emoji":"🍽️","meta":["французская кухня","закуска"],"description":"Деликатес из специально откормленной печени утки или гуся, отличающейся особенно нежной и жирной текстурой. Один из самых известных и одновременно спорных элементов французской гастрономии из-за метода откорма птицы.","fact":"Производство фуа-гра традиционным способом запрещено в ряде стран и регионов мира из-за вопросов, связанных с благополучием птиц.","wiki_en":"Foie gras"},{"name":"Тартар","emoji":"🥩","meta":["французская кухня","закуска"],"description":"Мелко рубленное сырое мясо, чаще всего говядина, заправленное каперсами, луком и специями, иногда с сырым яичным желтком сверху. Существует также рыбная версия блюда, например тартар из тунца или лосося.","fact":"Название блюда связывают с татарами, хотя историческая связь самого рецепта с их кухней остаётся спорной.","wiki_en":"Steak tartare"},{"name":"Макарон","emoji":"🍬","meta":["французская кухня","десерт"],"description":"Небольшое миндальное печенье-безе из двух половинок с хрустящей корочкой и мягкой сердцевиной, соединённых кремовой начинкой. Отличается яркими цветами и десятками вкусовых вариаций начинки.","fact":"Получить идеально гладкую поверхность и характерную «юбочку» у макарон считается одной из сложнейших задач в кондитерском деле.","wiki_en":"Macaron"},{"name":"Эклер","emoji":"🍫","meta":["французская кухня","десерт"],"description":"Продолговатое пирожное из заварного теста с начинкой из крема, чаще всего заварного, и глазурью сверху. Название переводится как «молния» — по одной из версий, из-за скорости, с которой его обычно съедают.","fact":"По одной из версий, название «эклер» связано с тем, что блестящая глазурь на пирожном напоминает вспышку молнии.","wiki_en":"Éclair"},{"name":"Профитроли","emoji":"🍫","meta":["французская кухня","десерт"],"description":"Небольшие шарики из заварного теста с начинкой из крема или мороженого, которые часто поливают шоколадным соусом. Из профитролей также складывают праздничный десерт-башню, скреплённую карамелью.","fact":"Башня из профитролей, скреплённых карамелью, традиционно подаётся на французских свадьбах вместо торта.","wiki_en":"Profiterole"},{"name":"Фондю","emoji":"🧀","meta":["швейцарская кухня","основное блюдо"],"description":"Расплавленный сыр с белым вином и чесноком в общем котелке, в который обмакивают кусочки хлеба на длинных вилках. Традиционное блюдо альпийских регионов Швейцарии и Франции, которое едят компанией за общим столом.","fact":"Существует также сладкая версия блюда — шоколадное фондю, в которое обмакивают фрукты и кусочки выпечки.","wiki_en":"Fondue"},{"name":"Раклет","emoji":"🧀","meta":["швейцарская кухня","основное блюдо"],"description":"Блюдо из расплавленного сыра, который соскабливают на отварной картофель, соленья и мясные закуски. Название происходит от французского глагола racler — «соскабливать», описывающего сам способ подачи.","fact":"Раклетом называют одновременно и сам сыр, и блюдо, и специальное устройство для его плавления за столом.","wiki_en":"Raclette"},{"name":"Венский шницель","emoji":"🍖","meta":["австрийская кухня","основное блюдо"],"description":"Тонко отбитое телячье филе в панировке из сухарей, обжаренное в большом количестве масла до золотистой хрустящей корочки. Один из главных символов австрийской кухни, который по традиции должен готовиться именно из телятины.","fact":"В Австрии существуют строгие представления о том, что настоящий венский шницель должен быть только телячьим, а не свиным.","wiki_en":"Wiener schnitzel"},{"name":"Братвурст","emoji":"🌭","meta":["немецкая кухня","основное блюдо"],"description":"Немецкая жареная или варёная колбаса из свинины или телятины с пряностями, которую подают с горчицей и хлебом или булочкой. Существуют десятки региональных вариаций рецепта по всей Германии.","fact":"В некоторых немецких регионах действуют строгие правила, регламентирующие рецептуру и даже размер местных братвурстов.","wiki_en":"Bratwurst"},{"name":"Брецель","emoji":"🥨","meta":["немецкая кухня","выпечка"],"description":"Витая сдобная выпечка характерной узловатой формы с хрустящей тёмной корочкой и мягкой серединой, которую перед выпечкой обрабатывают щелочным раствором. Один из главных символов баварской и немецкой кулинарной культуры.","fact":"Брецель издавна служил цеховым знаком пекарей — его изображение до сих пор встречается на вывесках булочных в Германии.","wiki_en":"Pretzel"},{"name":"Яблочный штрудель","emoji":"🍎","meta":["австрийская кухня","десерт"],"description":"Рулет из тончайшего вытяжного теста с начинкой из яблок, корицы, изюма и орехов, который запекают до хрустящей золотистой корочки. Один из главных десертов австрийской и в целом центральноевропейской кухни.","fact":"Тесто для настоящего штруделя вытягивают руками так тонко, что через него, по легенде, можно прочитать газетный текст.","wiki_en":"Strudel"},{"name":"Гуляш","emoji":"🍲","meta":["венгерская кухня","суп"],"description":"Густой суп или рагу из говядины с луком, паприкой и картофелем, который медленно тушится до насыщенного вкуса. Изначально блюдо пастухов, ставшее одним из главных символов венгерской национальной кухни.","fact":"Именно паприка, ставшая массовой в венгерской кухне лишь в XIX веке, придаёт гуляшу характерный красный цвет и вкус.","wiki_en":"Goulash"},{"name":"Фиш-энд-чипс","emoji":"🐟","meta":["британская кухня","основное блюдо"],"description":"Рыба в хрустящем кляре, обжаренная во фритюре, которую подают с крупно нарезанным жареным картофелем. Одно из самых узнаваемых блюд британской уличной еды, традиционно заворачиваемое в бумагу.","fact":"Блюдо стало настолько массовым в Британии, что во время Второй мировой войны его не включили в систему продовольственных карточек.","wiki_en":"Fish and chips"},{"name":"Английский завтрак","emoji":"🍳","meta":["британская кухня","основное блюдо"],"description":"Плотный завтрак из яичницы, бекона, сосисок, жареных томатов, грибов, фасоли в томатном соусе и тостов. Традиционное блюдо, которое подают в британских пабах и кафе в течение всего дня, а не только утром.","fact":"В Шотландии и Ирландии такой завтрак дополняют своими элементами — например, картофельными лепёшками или содовым хлебом.","wiki_en":"Full breakfast"},{"name":"Пастуший пирог","emoji":"🥧","meta":["британская кухня","основное блюдо"],"description":"Запеканка из тушёного мясного фарша, покрытая слоем картофельного пюре и запечённая до румяной корочки. Название связано с бараниной, которую традиционно использовали в начинке, — в отличие от говяжьей версии, называемой коттеджным пирогом.","fact":"Такие запеканки изначально готовили из остатков жаркого, а слой картофельного пюре заменял в них тесто.","wiki_en":"Shepherd's pie"},{"name":"Хот-дог","emoji":"🌭","meta":["американская кухня","основное блюдо"],"description":"Сосиска в разрезанной вдоль булочке, которую дополняют горчицей, кетчупом, луком и другими соусами по вкусу. Один из главных символов уличной еды США, тесно связанный с бейсбольными стадионами и уличными лотками.","fact":"Название «хот-дог» по одной из версий возникло из шутки о сходстве формы сосиски с таксой.","wiki_en":"Hot dog"},{"name":"Картофель фри","emoji":"🍟","meta":["бельгийская кухня","закуска"],"description":"Тонко нарезанные брусочки картофеля, обжаренные во фритюре до хрустящей корочки, часто дважды — сначала на низкой, потом на высокой температуре. Несмотря на название, ассоциируется в первую очередь не с Францией, а с Бельгией.","fact":"В Бельгии фри продают в специальных закусочных-фритюрницах и подают в бумажном конусе, чаще всего с майонезом.","wiki_en":"French fries"},{"name":"Стейк рибай","emoji":"🥩","meta":["стейковая кухня","основное блюдо"],"description":"Кусок говядины из реберной части туши с выраженными жировыми прослойками, которые делают мясо особенно сочным при прожарке. Один из самых популярных отрубов для стейка благодаря насыщенному вкусу и мягкой текстуре.","fact":"Жировые прожилки, которые делают рибай особенно сочным, называют мраморностью — она напрямую влияет на вкус мяса.","wiki_en":"Rib eye steak"},{"name":"Рёбрышки барбекю","emoji":"🍖","meta":["американская кухня","основное блюдо"],"description":"Свиные или говяжьи рёбра, которые долго готовят на медленном дыму и часто покрывают сладко-острым соусом барбекю. Блюдо тесно связано с южной кулинарной традицией США, где сложились разные региональные стили приготовления.","fact":"В разных штатах США существуют принципиально разные стили барбекю, различающиеся составом соуса и способом дымления мяса.","wiki_en":"Barbecue"},{"name":"Жареная курица","emoji":"🍗","meta":["американская кухня","основное блюдо"],"description":"Куски курицы, обмакнутые в специи и муку или тесто, обжаренные во фритюре до хрустящей корочки. Одно из главных блюд южной кухни США, ставшее впоследствии основой глобальной сети фастфуда.","fact":"Рецепты южной жареной курицы в США восходят к кулинарным традициям, привезённым как европейскими переселенцами, так и африканскими рабами.","wiki_en":"Fried chicken"},{"name":"Крылышки баффало","emoji":"🍗","meta":["американская кухня","закуска"],"description":"Куриные крылышки, обжаренные во фритюре и покрытые острым соусом на основе кайенского перца и масла, подаются с соусом блю чиз и сельдереем. Придумали блюдо в баре в городе Буффало, штат Нью-Йорк, откуда оно и получило название.","fact":"В самом Буффало каждый год проводят фестиваль, целиком посвящённый куриным крылышкам и соусам к ним.","wiki_en":"Buffalo wing"},{"name":"Мак-н-чиз","emoji":"🧀","meta":["американская кухня","основное блюдо"],"description":"Макароны в густом сырном соусе, которые часто дополнительно запекают в духовке до румяной корочки сверху. Одно из самых домашних и узнаваемых блюд американской кухни, любимое как детьми, так и взрослыми.","fact":"Рецепты, похожие на макароны с сыром, встречаются в европейских кулинарных книгах ещё задолго до того, как блюдо стало символом американской кухни.","wiki_en":"Macaroni and cheese"},{"name":"Клаб-сэндвич","emoji":"🥪","meta":["американская кухня","основное блюдо"],"description":"Многослойный сэндвич из нескольких кусков тоста с курицей, беконом, салатом, помидорами и майонезом, который обычно разрезают на треугольники и скрепляют шпажками. Классика меню американских кафе и отелей.","fact":"Откуда в названии взялось слово «клаб», точно неизвестно — чаще всего его связывают с закрытыми джентльменскими клубами.","wiki_en":"Club sandwich"},{"name":"Бейгл с лососем","emoji":"🥯","meta":["американская кухня","основное блюдо"],"description":"Плотная бублик-булочка бейгл, разрезанная пополам, намазанная сливочным сыром и дополненная тонко нарезанным копчёным или солёным лососем. Блюдо тесно связано с еврейской кулинарной традицией Нью-Йорка.","fact":"Традиция сочетать бейгл со сливочным сыром и лососем сложилась в еврейских общинах Нью-Йорка в конце XIX — начале XX века.","wiki_en":"Lox"},{"name":"Яйца Бенедикт","emoji":"🍳","meta":["американская кухня","основное блюдо"],"description":"Английская булочка с ветчиной или беконом, яйцом-пашот и соусом голландез, который подают горячим на завтрак или бранч. Существует несколько версий истории появления блюда, все они связаны с Нью-Йорком конца XIX века.","fact":"По одной из версий, блюдо придумали для завсегдатая ресторана, попросившего сделать ему что-то новое против похмелья.","wiki_en":"Eggs Benedict"},{"name":"Панкейки","emoji":"🥞","meta":["американская кухня","основное блюдо"],"description":"Пышные оладьи из жидкого теста на разрыхлителе, которые обжаривают на сковороде и подают стопкой с кленовым сиропом и маслом. Классическое блюдо американского завтрака, отличающееся от тонких блинов пористой воздушной текстурой.","fact":"Пышность американских панкейков достигается за счёт разрыхлителя в тесте, в отличие от более тонких блинов на дрожжах.","wiki_en":"Pancake"},{"name":"Бельгийские вафли","emoji":"🧇","meta":["бельгийская кухня","десерт"],"description":"Толстые вафли с глубокими ячейками, которые получаются особенно хрустящими снаружи и мягкими внутри благодаря дрожжевому тесту. Подают со взбитыми сливками, ягодами, шоколадным соусом или сахарной пудрой.","fact":"Глубокие ячейки бельгийских вафель отлично удерживают начинку — сироп, ягоды или взбитые сливки не стекают с поверхности.","wiki_en":"Belgian waffle"},{"name":"Пончики","emoji":"🍩","meta":["американская кухня","десерт"],"description":"Обжаренные во фритюре кольца или шарики из сдобного теста, покрытые глазурью, сахарной пудрой или посыпкой. Один из самых узнаваемых десертов США, вокруг которого выросла целая сеть специализированных кафе.","fact":"В США существует неофициальный Национальный день пончика, отмечаемый ещё с 1930-х годов.","wiki_en":"Doughnut"},{"name":"Брауни","emoji":"🍫","meta":["американская кухня","десерт"],"description":"Плотный шоколадный пирог с влажной, почти тягучей текстурой внутри и тонкой корочкой сверху, часто с орехами. Название происходит от коричневого цвета выпечки и её характерной шоколадной плотности.","fact":"Идеальный брауни балансирует между пирожным и печеньем — именно эта промежуточная текстура считается признаком удачного рецепта.","wiki_en":"Chocolate brownie"},{"name":"Чизкейк","emoji":"🍰","meta":["американская кухня","десерт"],"description":"Десерт из сливочного или творожного сыра на основе из печенья, который запекают или готовят без выпечки и часто дополняют ягодным соусом. Современная американская версия, особенно нью-йоркский стиль, стала самой известной в мире.","fact":"Простейшие прообразы творожных десертов, похожих на чизкейк, существовали ещё в Древней Греции, задолго до появления современного рецепта.","wiki_en":"Cheesecake"},{"name":"Яблочный пай","emoji":"🥧","meta":["американская кухня","десерт"],"description":"Открытый или закрытый пирог из песочного теста с начинкой из яблок, корицы и сахара, один из главных символов американской домашней кухни. Фраза «американский, как яблочный пай» отражает его особый культурный статус в США.","fact":"Домашние яблони в Северную Америку привезли европейские колонисты — до них там росли только дикие виды.","wiki_en":"Apple pie"},{"name":"Морковный торт","emoji":"🥕","meta":["американская кухня","десерт"],"description":"Пряный бисквит на основе тёртой моркови, орехов и специй, который обычно покрывают кремом на основе сливочного сыра. Сладость моркови и жирная текстура крема делают этот торт особенно сочным и насыщенным.","fact":"Морковь начали активно использовать в выпечке ещё в Средние века как доступный источник природной сладости, когда сахар был дорог.","wiki_en":"Carrot cake"},{"name":"Торт «Красный бархат»","emoji":"🍰","meta":["американская кухня","десерт"],"description":"Бисквитный торт насыщенного красного цвета с лёгким какао-вкусом, который обычно прослаивают кремом на основе сливочного сыра. Яркий цвет исторически достигался реакцией какао с определёнными ингредиентами теста, а сегодня чаще пищевым красителем.","fact":"Славу торту в США во многом принёс ресторан отеля «Уолдорф-Астория» в Нью-Йорке, где его подавали как своё фирменное блюдо.","wiki_en":"Red velvet cake"},{"name":"Торт «Павлова»","emoji":"🍰","meta":["австрало-новозеландская кухня","десерт"],"description":"Десерт из хрустящей снаружи и мягкой внутри безе-основы, украшенной взбитыми сливками и свежими фруктами, чаще всего ягодами и киви. Назван в честь русской балерины Анны Павловой, гастролировавшей по Австралии и Новой Зеландии.","fact":"Австралия и Новая Зеландия до сих пор спорят между собой о том, в какой из двух стран был придуман этот десерт.","wiki_en":"Pavlova (cake)"},{"name":"Мороженое","emoji":"🍦","meta":["мировая кухня","десерт"],"description":"Замороженный сладкий десерт на основе молока, сливок или воды с сахаром и добавками, известный человечеству в разных формах уже много веков. Существуют десятки видов и техник приготовления — от джелато до мягкого мороженого.","fact":"Прообразы мороженого — замороженные фруктовые смеси со снегом и льдом — существовали ещё в древних цивилизациях задолго до холодильной техники.","wiki_en":"Ice cream"},{"name":"Салат «Цезарь»","emoji":"🥗","meta":["американская кухня","закуска"],"description":"Салат из листьев ромена, сухариков, пармезана и заправки на основе яйца, чеснока, анчоусов и лимонного сока. Придумал его ресторатор итальянского происхождения в Мексике, а не в самой Италии или США.","fact":"По легенде, салат придумали буквально из подручных продуктов, оставшихся на кухне ресторана в момент, когда закончились основные запасы.","wiki_en":"Caesar salad"},{"name":"Греческий салат","emoji":"🥗","meta":["греческая кухня","закуска"],"description":"Салат из помидоров, огурцов, красного лука, оливок и крупного куска сыра фета, заправленный оливковым маслом. Один из главных символов греческой кухни, узнаваемый по яркому сочетанию свежих овощей и солёного сыра.","fact":"В самой Греции такой салат чаще называют просто «деревенским», а не «греческим».","wiki_en":"Greek salad"},{"name":"Мусака","emoji":"🍆","meta":["греческая кухня","основное блюдо"],"description":"Слоёная запеканка из баклажанов, мясного фарша и соуса бешамель, запечённая до румяной корочки сверху. Одно из главных блюд греческой кухни, хотя похожие запеканки встречаются и на Балканах, и на Ближнем Востоке.","fact":"Современный греческий рецепт мусаки с бешамелем сверху сформировался под явным влиянием французской кулинарной техники в начале XX века.","wiki_en":"Moussaka"},{"name":"Гирос","emoji":"🌯","meta":["греческая кухня","основное блюдо"],"description":"Мясо, обжаренное на вертикальном вертеле, тонко нарезанное и завёрнутое в лепёшку питта с овощами и соусом дзадзики. Греческий аналог турецкого дёнера, ставший одним из самых популярных блюд уличной еды Греции.","fact":"Слово «гирос» в переводе с греческого означает «поворот» или «круг» — по способу вращения мяса на вертеле.","wiki_en":"Gyro (food)"},{"name":"Севиче","emoji":"🐟","meta":["латиноамериканская кухня","закуска"],"description":"Сырая рыба или морепродукты, маринованные в соке лайма или лимона с луком и перцем чили, — кислота как бы «доготавливает» рыбу без нагрева. Блюдо особенно популярно в Перу, которое считается одним из его основных центров происхождения.","fact":"Кислота цитрусового сока меняет структуру белка в рыбе почти так же, как это делает тепловая обработка, — поэтому рыба выглядит «приготовленной».","wiki_en":"Ceviche"},{"name":"Эмпанадас","emoji":"🥟","meta":["латиноамериканская кухня","закуска"],"description":"Пирожки из теста с начинкой из мяса, сыра или овощей, которые запекают или обжаривают до золотистой корочки. Распространены по всей Латинской Америке и Испании, при этом в каждой стране есть свои варианты начинки и формы.","fact":"Форма и способ защипывания краёв эмпанадас в некоторых странах Латинской Америки помогают определить начинку ещё до того, как пирожок надкусили.","wiki_en":"Empanada"},{"name":"Фейжоада","emoji":"🍲","meta":["бразильская кухня","основное блюдо"],"description":"Густое тушёное блюдо из чёрной фасоли с разными видами свинины и говядины, которое традиционно подают с рисом, капустой и апельсинами. Считается национальным блюдом Бразилии и часто готовится по выходным как повод собраться большой компанией.","fact":"В Бразилии сложилась традиция подавать фейжоаду именно по субботам, собирая за столом семью и друзей.","wiki_en":"Feijoada"},{"name":"Путин","emoji":"🍟","meta":["канадская кухня","основное блюдо"],"description":"Картофель фри, политый горячим мясным соусом и посыпанный сырными сгустками, которые слегка подтаивают под теплом соуса. Блюдо родом из канадской провинции Квебек, где оно возникло в сельских закусочных в XX веке.","fact":"Название блюда не связано с политиками — оно происходит от квебекского сленгового слова, обозначающего нечто вроде «месива».","wiki_en":"Poutine"},{"name":"Сэндвич «Филли Чизстейк»","emoji":"🧀","meta":["американская кухня","сэндвич"],"description":"Горячий сэндвич из тонко нарезанной говядины и расплавленного сыра в длинной булке, придуманный в Филадельфии уличными торговцами хот-догами. Сегодня это один из главных символов города, а споры о «правильном» сыре — чиз-виз или проволоне — не утихают среди местных жителей.","fact":"В Филадельфии существуют десятки закусочных, яростно спорящих о том, чья версия сэндвича «настоящая».","wiki_en":"Cheesesteak"},{"name":"Сэндвич «Рубен»","emoji":"🥪","meta":["американская кухня","сэндвич"],"description":"Слоёный сэндвич из ржаного хлеба, солонины, квашеной капусты, швейцарского сыра и соуса «тысяча островов», обжаренный на гриле до хрустящей корочки. Его происхождение приписывают то нью-йоркскому, то небрасскому ресторатору по фамилии Рубен, но точная история остаётся предметом споров.","fact":"Несмотря на споры об авторстве, сэндвич давно стал классикой меню американских деликатесных.","wiki_en":"Reuben sandwich"},{"name":"Сэндвич БЛТ","emoji":"🥓","meta":["американская кухня","сэндвич"],"description":"Простой сэндвич из бекона, листьев салата и ломтиков помидора между двумя кусками поджаренного хлеба, часто с майонезом. Его название — просто аббревиатура ингредиентов, а сама комбинация стала одной из самых узнаваемых в американской кухне.","fact":"Название БЛТ (bacon, lettuce, tomato) настолько прижилось, что в меню редко пишут его полностью.","wiki_en":"BLT"},{"name":"Сэндвич с арахисовым маслом и джемом","emoji":"🥜","meta":["американская кухня","сэндвич"],"description":"Два куска хлеба с арахисовой пастой и фруктовым джемом — классический школьный обед в США, который готовят практически в каждом доме. Сочетание солёного и сладкого вкусов сделало его одним из символов американского детства.","fact":"В США сэндвич настолько привычен, что его называют просто PB&J — по первым буквам английских названий ингредиентов.","wiki_en":"Peanut butter and jelly sandwich"},{"name":"По-бой","emoji":"🍤","meta":["американская кухня","сэндвич"],"description":"Луизианский сэндвич на длинной хрустящей булке, который начиняют жареными креветками, устрицами, ростбифом или другой начинкой на выбор. По легенде, название связано со словом «бедняк» — так называли забастовщиков трамвайной компании, которых бесплатно кормили этим сэндвичем.","fact":"В Луизиане заказ «dressed» означает, что сэндвич подадут с салатом, помидором, соленьями и майонезом.","wiki_en":"Po' boy"},{"name":"Слоппи Джо","emoji":"🍅","meta":["американская кухня","сэндвич"],"description":"Булка с рыхлой начинкой из обжаренного фарша в томатном соусе, который неизбежно капает по рукам — отсюда и «неряшливое» название. Простое и недорогое блюдо стало любимым в американских школьных столовых и домашней кухне.","fact":"Название «слоппи» намекает именно на то, что есть его аккуратно почти невозможно.","wiki_en":"Sloppy joe"},{"name":"Мясной рулет","emoji":"🍖","meta":["американская кухня","основное блюдо"],"description":"Запечённая буханка из фарша, яиц, панировочных сухарей и специй, часто покрытая сверху томатным или кетчупным соусом. Это классическое блюдо домашней американской кухни, которое ассоциируется с воскресным семейным ужином.","fact":"В США существует даже неофициальный «Национальный день мясного рулета».","wiki_en":"Meatloaf"},{"name":"Салат «Кобб»","emoji":"🥗","meta":["американская кухня","салат"],"description":"Салат из аккуратных рядов курицы, бекона, яиц, авокадо, помидоров и сыра рокфор на подложке из зелени. По легенде, его придумали в голливудском ресторане в конце 1930-х, когда владелец заведения собрал блюдо из остатков продуктов на кухне.","fact":"Салат носит имя Боба Кобба, владельца голливудского ресторана «Браун Дерби», где его и стали подавать.","wiki_en":"Cobb salad"},{"name":"Салат «Уолдорф»","emoji":"🍏","meta":["американская кухня","салат"],"description":"Салат из яблок, сельдерея, грецких орехов и майонеза, иногда с добавлением винограда, придуманный в нью-йоркском отеле «Уолдорф-Астория». Его хрустящая текстура и сладко-пряный вкус сделали салат одним из символов американской ресторанной классики.","fact":"Изначально в рецепте не было орехов — их добавили уже позже, когда салат стал популярным.","wiki_en":"Waldorf salad"},{"name":"Печенье с шоколадной крошкой","emoji":"🍪","meta":["американская кухня","десерт"],"description":"Рассыпчатое печенье с кусочками шоколада, придуманное в 1930-х годах в гостинице Toll House в Массачусетсе. Считается, что рецепт возник случайно, когда хозяйка добавила в тесто наколотую шоколадную плитку вместо какао-порошка.","fact":"Название Toll House закрепилось за рецептом: его до сих пор печатают на упаковках шоколадной крошки Nestlé.","wiki_en":"Chocolate chip cookie"},{"name":"Пекановый пирог","emoji":"🥧","meta":["американская кухня","десерт"],"description":"Пирог с начинкой из орехов пекан, яиц, сахара и сиропа, который при выпечке становится плотным и карамельно-тягучим. Блюдо особенно популярно на юге США, где растут сами орехи пекан, и традиционно подаётся на День благодарения.","fact":"Пекан — близкий родственник гикори, а его дерево выбрано официальным деревом штата Техас.","wiki_en":"Pecan pie"},{"name":"Тыквенный пирог","emoji":"🎃","meta":["американская кухня","десерт"],"description":"Пирог с пряной начинкой из тыквенного пюре, яиц и специй вроде корицы и мускатного ореха, выпекаемый в песочной основе. Это неизменный десерт на американском Дне благодарения, символизирующий осенний урожай.","fact":"Большинство домашних тыквенных пирогов в США печут не из свежей тыквы, а из готового консервированного пюре.","wiki_en":"Pumpkin pie"},{"name":"Пирог «Ки-лайм»","emoji":"🍋","meta":["американская кухня","десерт"],"description":"Пирог с кисло-сладкой начинкой из сока флоридских лаймов ки, сгущённого молока и яичных желтков на песочной или крошковой основе. Родом из Флорида-Кис, он отличается ярким жёлтым цветом и освежающим вкусом.","fact":"Настоящий ки-лайм пирог никогда не бывает зелёным — его естественный цвет желтоватый.","wiki_en":"Key lime pie"},{"name":"Банановый пудинг","emoji":"🍌","meta":["американская кухня","десерт"],"description":"Слоёный десерт из ванильного заварного крема, печенья и ломтиков банана, который настаивается в холодильнике, пока печенье не размягчится. Это классика южной американской кухни, часто подаваемая на семейных застольях.","fact":"Рецепт этого пудинга долгие годы печатали прямо на упаковке ванильного печенья Nilla Wafers.","wiki_en":"Banana pudding"},{"name":"Персиковый коблер","emoji":"🍑","meta":["американская кухня","десерт"],"description":"Тёплый десерт из запечённых персиков под слоем рассыпчатого теста, напоминающего толстую корочку без строгой формы. Название «коблер» отражает грубоватый, «залатанный» вид верхнего слоя, а блюдо особенно любимо на юге США.","fact":"Коблеры возникли у поселенцев, у которых не было привычных ингредиентов для классического английского пирога.","wiki_en":"Cobbler (food)"},{"name":"Кукурузный хлеб","emoji":"🌽","meta":["американская кухня","хлеб"],"description":"Плотный хлеб из кукурузной муки, который выпекают на сковороде или в форме и подают тёплым со сливочным маслом. Это неотъемлемая часть южной американской кухни, часто сопровождающая тушёные блюда и барбекю.","fact":"В разных регионах США спорят, должен ли кукурузный хлеб быть сладким или несладким.","wiki_en":"Cornbread"},{"name":"Пирог с курицей","emoji":"🍗","meta":["американская кухня","основное блюдо"],"description":"Закрытый пирог с начинкой из курицы, овощей и густого сливочного соуса под хрустящей корочкой из теста. Это сытное домашнее блюдо стало символом уютной американской кухни и часто ассоциируется с семейными ужинами.","fact":"В английском языке выражение «pot pie» используют и для схожих блюд с другой начинкой, не только куриной.","wiki_en":"Pot pie"},{"name":"Овсяное печенье","emoji":"🌾","meta":["американская кухня","десерт"],"description":"Плотное рассыпчатое печенье из овсяных хлопьев, часто с изюмом или корицей, которое выпекают до золотистой хрустящей корочки. Считается более «полезной» альтернативой обычному сдобному печенью благодаря клетчатке овсянки.","fact":"Рецепты овсяного печенья разошлись по Америке во многом благодаря производителям хлопьев, печатавшим их на упаковках.","wiki_en":"Oatmeal cookie"},{"name":"Корн-дог","emoji":"🌭","meta":["американская кухня","уличная еда"],"description":"Сосиска на палочке, обмакнутая в кукурузное тесто и обжаренная во фритюре до румяной корочки. Это классика американских ярмарок и уличных фестивалей, которую едят на ходу, держа за деревянную палочку.","fact":"Ежегодно на ярмарке штата Техас продают сотни тысяч таких корн-догов.","wiki_en":"Corn dog"},{"name":"Луковые кольца","emoji":"🧅","meta":["американская кухня","закуска"],"description":"Кольца репчатого лука в хрустящей панировке, обжаренные во фритюре до золотистого цвета, — популярная закуска к бургерам и стейкам. Их подают почти в каждой американской закусочной как альтернативу картофелю фри.","fact":"В некоторых закусочных луковые кольца готовят из целой крупной луковицы, разбираемой на отдельные слои-кольца.","wiki_en":"Onion ring"},{"name":"Молочный коктейль","emoji":"🥤","meta":["американская кухня","напиток"],"description":"Густой напиток из молока, мороженого и сиропа, взбитый до пышной пенки, часто подают с трубочкой в высоком стакане. Он стал неотъемлемой частью американских закусочных и придорожных кафе середины XX века.","fact":"Первые молочные коктейли готовили без мороженого — просто взбивали молоко с сиропом и содовой.","wiki_en":"Milkshake"},{"name":"Мороженое «Санде»","emoji":"🍨","meta":["американская кухня","десерт"],"description":"Шарики мороженого, политые сиропом или шоколадом, украшенные взбитыми сливками, орехами и вишенкой сверху. По легенде, десерт появился как способ обойти законы, запрещавшие продажу газировки с мороженым по воскресеньям.","fact":"Города Итака в штате Нью-Йорк и Ту-Риверс в Висконсине до сих пор спорят, где санде подали впервые.","wiki_en":"Sundae"},{"name":"Банана-сплит","emoji":"🍧","meta":["американская кухня","десерт"],"description":"Разрезанный вдоль банан, на который выкладывают несколько шариков мороженого разных вкусов, сироп, взбитые сливки и орехи. Это один из самых узнаваемых десертов американских кафе-мороженых начала XX века.","fact":"Считается, что рецепт придумал аптекарь из Пенсильвании, искавший способ выделиться среди конкурентов.","wiki_en":"Banana split"},{"name":"Печёные бобы","emoji":"🫘","meta":["американская кухня","гарнир"],"description":"Белая фасоль, томлённая в сладковато-пряном соусе с патокой или кетчупом, часто с кусочками бекона. Это традиционный гарнир американских барбекю и пикников, особенно распространённый на северо-востоке США.","fact":"В Бостоне печёные бобы настолько популярны, что город прозвали «Бинтаун» — «бобовый город».","wiki_en":"Baked beans"},{"name":"Коулслоу","emoji":"🥬","meta":["американская кухня","салат"],"description":"Салат из тонко нашинкованной капусты и моркови, заправленный майонезом или уксусной заправкой, — обязательный гарнир к барбекю и жареной рыбе. Название происходит от голландского слова, означающего «капустный салат».","fact":"Рецепт коулслоу в США завезли голландские колонисты ещё в XVIII веке.","wiki_en":"Coleslaw"},{"name":"Пулд-порк","emoji":"🐖","meta":["американская кухня","основное блюдо"],"description":"Свиная лопатка, медленно томлённая или копчённая до полной мягкости, а затем разобранная руками или вилками на волокна. Подают его обычно с булочкой и соусом барбекю как основу для сэндвича на юге США.","fact":"Приготовление классического пулд-порка на коптильне может занимать целые сутки.","wiki_en":"Pulled pork"},{"name":"Техасский брискет","emoji":"🥩","meta":["американская кухня","основное блюдо"],"description":"Говяжья грудинка, которую коптят на дровах много часов подряд до образования плотной тёмной корочки и тающей внутри мякоти. Это визитная карточка техасского барбекю, вокруг приготовления которого сложилась целая культура соревнований питмастеров.","fact":"Опытные питмастера коптят брискет по 12–16 часов, добиваясь фирменной «дымной каёмки» под коркой.","wiki_en":"Brisket"},{"name":"Джамбалая","emoji":"🍚","meta":["американская кухня","основное блюдо"],"description":"Луизианское блюдо из риса, тушённого вместе с колбасками, курицей или морепродуктами, овощами и специями каджунской или креольской кухни. Оно родилось как результат смешения французских, испанских и африканских кулинарных традиций Нового Орлеана.","fact":"Джамбалая считается дальней родственницей испанской паэльи, привезённой в Луизиану колонистами.","wiki_en":"Jambalaya"},{"name":"Гритс","emoji":"🥣","meta":["американская кухня","гарнир"],"description":"Каша из грубо смолотой кукурузы, которую варят до кремовой консистенции и подают на завтрак с маслом, сыром или креветками. Это одно из главных блюд кухни южных штатов США, корни которого уходят к рецептам коренных американцев.","fact":"Классический завтрак «креветки с гритсом» стал визитной карточкой прибрежной кухни Южной Каролины.","wiki_en":"Grits"},{"name":"Клэм-чаудер","emoji":"🦪","meta":["американская кухня","суп"],"description":"Густой сливочный суп с моллюсками, картофелем и беконом, который особенно популярен в Новой Англии на северо-востоке США. Его часто подают в выдолбленной буханке хлеба вместо тарелки, особенно в Сан-Франциско.","fact":"В Новой Англии бытует шутка о законе, по которому в классический белый чаудер запрещено добавлять томаты.","wiki_en":"Clam chowder"},{"name":"Крабовые котлеты","emoji":"🦀","meta":["американская кухня","основное блюдо"],"description":"Обжаренные котлеты из крабового мяса, панировочных сухарей и специй, которые особенно ценят за нежный сладковатый вкус самого краба. Блюдо тесно связано с кухней штата Мэриленд, где ловят крабов особого вида.","fact":"В Мэриленде лучшими считаются котлеты, где крабового мяса больше, чем панировки и наполнителя.","wiki_en":"Crab cake"},{"name":"Лобстер-ролл","emoji":"🦞","meta":["американская кухня","сэндвич"],"description":"Булка с кусочками отварного лобстерового мяса, заправленными майонезом или топлёным маслом, — фирменное блюдо побережья Новой Англии. Простота рецепта позволяет в полной мере ощутить вкус самого лобстера.","fact":"В штатах Мэн и Коннектикут существуют две конкурирующие традиции — с майонезом и с маслом.","wiki_en":"Lobster roll"},{"name":"Французские тосты","emoji":"🍞","meta":["американская кухня","завтрак"],"description":"Ломтики хлеба, вымоченные во взбитых яйцах с молоком и обжаренные на сковороде до золотистой корочки, подаются с сиропом или ягодами. Несмотря на название, похожие рецепты использования зачерствевшего хлеба существовали в европейской кухне задолго до Франции.","fact":"Похожие блюда из размоченного в яйце хлеба известны в Европе ещё со времён Средневековья.","wiki_en":"French toast"},{"name":"Хэш-браун","emoji":"🥔","meta":["американская кухня","завтрак"],"description":"Тёртый или мелко нарезанный картофель, обжаренный на сковороде до хрустящей золотистой корочки, — обязательная часть американского завтрака. Подают его как в виде рыхлой массы, так и спрессованным в аккуратный брусок или котлетку.","fact":"В сетях фастфуда хэш-браун часто формуют в виде плоского прямоугольного брикета для удобства подачи.","wiki_en":"Hash browns"},{"name":"Булочка с корицей","emoji":"🍥","meta":["американская кухня","выпечка"],"description":"Сдобная булочка со спиральной начинкой из масла, сахара и корицы, часто покрытая сверху сахарной или сливочной глазурью. Рецепт пришёл из скандинавской и немецкой выпечки, но особую популярность приобрёл именно в США.","fact":"Аромат свежих булочек с корицей стал фирменным маркетинговым приёмом сети Cinnabon в торговых центрах.","wiki_en":"Cinnamon roll"},{"name":"Фаннел-кейк","emoji":"🍩","meta":["американская кухня","уличная еда"],"description":"Жидкое тесто, вылитое через воронку в кипящее масло тонкими струями, обжаривается до хрустящей сетчатой лепёшки и посыпается сахарной пудрой. Это классическое лакомство американских ярмарок и парков развлечений.","fact":"Название «воронковый пирог» происходит именно от воронки, через которую льют тесто в масло.","wiki_en":"Funnel cake"},{"name":"Гамбо","emoji":"🍲","meta":["американская кухня","суп"],"description":"Густой луизианский суп на основе заправки ру, с курицей, колбасками или морепродуктами, овощами «святой троицы» и специями. Блюдо объединяет французские, африканские, испанские и коренные американские кулинарные традиции Нового Орлеана.","fact":"Название блюда, вероятно, восходит к западноафриканскому слову, обозначающему окру — один из традиционных ингредиентов.","wiki_en":"Gumbo"},{"name":"Сэндвич с пастрами","emoji":"🥪","meta":["американская кухня","сэндвич"],"description":"Сэндвич из толстого слоя копчёной и приправленной специями говядины на ржаном хлебе, ставший визитной карточкой нью-йоркских еврейских деликатесных. Мясо перед подачей долго готовят на пару, чтобы оно стало особенно мягким.","fact":"В некоторых нью-йоркских деликатесных порция пастрами в сэндвиче может весить больше полукилограмма.","wiki_en":"Pastrami on rye"},{"name":"Салат «Мимоза»","emoji":"🥚","meta":["советская кухня","салат"],"description":"Слоёный салат из консервированной рыбы, варёных яиц, сыра и лука под майонезом, верхний слой которого посыпают протёртым яичным желтком. Жёлтая рассыпчатая «пудра» напоминает цветки мимозы, откуда и пошло название блюда.","fact":"Название салата связано исключительно с внешним видом — растения мимозы в составе блюда нет.","wiki_en":"Mimosa salad"},{"name":"Салат «Крабовый»","emoji":"🥣","meta":["постсоветская кухня","салат"],"description":"Салат из крабовых палочек, риса, кукурузы, яиц и майонеза, ставший одним из самых популярных праздничных блюд на постсоветском пространстве в 1990-е годы. Несмотря на название, настоящего крабового мяса в нём почти никогда не бывает.","fact":"Популярность салата в 1990-х во многом связана с широким распространением недорогих крабовых палочек.","wiki_en":"Crab salad"},{"name":"Заливное","emoji":"🐟","meta":["русская кухня","закуска"],"description":"Кусочки мяса, рыбы или языка, залитые прозрачным застывшим бульоном на основе желатина или натурального желирующего эффекта хрящей. Блюдо традиционно подают холодным на праздничный стол, часто на Новый год.","fact":"Прозрачность заливного считается признаком мастерства повара — бульон для него долго и тщательно осветляют.","wiki_en":"Aspic"},{"name":"Расстегай","emoji":"🥟","meta":["русская кухня","выпечка"],"description":"Открытый пирожок из дрожжевого теста с начинкой из рыбы, мяса или визиги, у которого верх специально оставляют приоткрытым. Отверстие сверху позволяет перед подачей добавить в пирожок немного бульона или масла.","fact":"Открытая верхушка пирожка дала ему название — от глагола «расстегнуть».","wiki_en":"Rasstegai"},{"name":"Кулебяка","emoji":"🥧","meta":["русская кухня","выпечка"],"description":"Продолговатый закрытый пирог из дрожжевого теста с несколькими слоями начинки — рыбой, мясом, капустой, грибами или кашей, переложенными тонкими блинами. Это одно из самых торжественных и трудоёмких блюд классической русской кухни.","fact":"Французская кухня переняла кулебяку под названием «кулибьяк» — чаще всего её делают с лососем и рисом.","wiki_en":"Coulibiac"},{"name":"Кутья","emoji":"🌾","meta":["славянская кухня","каша"],"description":"Сладкая каша из цельных зёрен пшеницы или риса с мёдом, маком и изюмом, которую готовят на поминки и на Рождество. Каждый ингредиент в блюде несёт символическое значение — от зерна как знака жизни до мёда как символа благополучия.","fact":"На Рождество кутью традиционно едят первой, начиная с неё праздничную трапезу — сочельник.","wiki_en":"Kutia"},{"name":"Кисель","emoji":"🍇","meta":["русская кухня","напиток"],"description":"Густой напиток из ягодного или фруктового сока, загущённого крахмалом, который может быть как питьевым, так и настолько плотным, что его едят ложкой. Изначально на Руси кисель готовили не из ягод, а на основе овсяного или ржаного отвара.","fact":"Старинный овсяный кисель застывал так плотно, что его нарезали ножом и ели ломтями, а не пили.","wiki_en":"Kissel"},{"name":"Компот","emoji":"🍒","meta":["русская кухня","напиток"],"description":"Напиток из свежих или сушёных фруктов и ягод, сваренных в подслащённой воде, — привычная часть обеда в домах и столовых постсоветского пространства. Его готовят практически из любых сезонных плодов, от яблок до сухофруктов.","fact":"В советских столовых компот почти всегда подавали как обязательный третий пункт комплексного обеда.","wiki_en":"Kompot"},{"name":"Морс","emoji":"🫐","meta":["русская кухня","напиток"],"description":"Освежающий напиток из отжатого сока ягод, разбавленного водой и подслащённого, чаще всего готовят из клюквы или брусники. Морс традиционно считался в русской кухне не только вкусным, но и полезным при простуде напитком.","fact":"От компота морс отличается тем, что ягоды в нём не варят долго: сок отжимают и добавляют в отвар уже под конец.","wiki_en":"Mors (drink)"},{"name":"Квас","emoji":"🧃","meta":["русская кухня","напиток"],"description":"Слабо газированный напиток на основе брожения ржаного хлеба или солода, обладающий характерным кисловатым вкусом. Летом его традиционно продавали в бочках прямо на улицах, а на его основе готовят холодный суп окрошку.","fact":"Естественное брожение даёт квасу совсем небольшую крепость — около процента, поэтому его считают безалкогольным.","wiki_en":"Kvass"},{"name":"Сбитень","emoji":"☕","meta":["русская кухня","напиток"],"description":"Горячий напиток на основе мёда и пряностей вроде корицы, гвоздики или имбиря, который пили на Руси задолго до появления чая. Его подавали как согревающий зимний напиток, часто на ярмарках прямо с раскалённых самоваров.","fact":"Разносчики-сбитенщики торговали им прямо на улицах, нося напиток в больших медных сосудах с краном.","wiki_en":"Sbiten"},{"name":"Медовуха","emoji":"🍯","meta":["русская кухня","напиток"],"description":"Слабоалкогольный напиток на основе мёда, воды и дрожжей, иногда с добавлением ягод или пряностей, получаемый естественным брожением. Один из древнейших алкогольных напитков славян, который переживает возрождение как часть исторической кухни.","fact":"В России медовуха стала гастрономическим сувениром Суздаля, где её варят и продают туристам.","wiki_en":"Medovukha"},{"name":"Пастила","emoji":"🍬","meta":["русская кухня","десерт"],"description":"Воздушное лакомство из взбитого яблочного пюре с сахаром и яичным белком, высушенное до лёгкой пастообразной текстуры. Особенно известна коломенская и белёвская пастила, изготовление которых по старинным рецептам стало местной гастрономической гордостью.","fact":"Традиционная белёвская пастила делается из кислых сортов яблок, дающих особенно нежную структуру десерта.","wiki_en":"Pastila"},{"name":"Зефир","emoji":"☁️","meta":["русская кухня","десерт"],"description":"Пышный десерт из взбитого фруктового пюре с сахаром и загустителем, застывающий в виде воздушных половинок, соединённых донышками. Он считается более лёгкой родственницей пастилы и одной из самых узнаваемых сладостей русского чаепития.","fact":"Форму зефиру придаёт не желатин, а агар-агар или пектин — именно поэтому он остаётся таким воздушным.","wiki_en":"Zefir (food)","wiki_ru":"Зефир (кулинария)"},{"name":"Тульский пряник","emoji":"🍪","meta":["русская кухня","выпечка"],"description":"Плотный пряник с начинкой из повидла и узором, отпечатанным при помощи резной деревянной формы, — гастрономический символ города Тулы. Традиция изготовления таких пряников насчитывает несколько веков и до сих пор жива в местных пекарнях.","fact":"Узор режут на деревянной пряничной доске в зеркальном виде, чтобы на готовом прянике он получился правильным.","wiki_en":"Pryanik"},{"name":"Сгущёнка","emoji":"🥫","meta":["советская кухня","десерт"],"description":"Сладкое загущённое молоко, уваренное с сахаром до густой тягучей консистенции, которое едят как самостоятельное лакомство или добавляют в выпечку и напитки. Банка сгущённого молока с бело-синей этикеткой стала одним из узнаваемых образов советской продуктовой культуры.","fact":"Варёная сгущёнка, которую получают долгим кипячением закрытой банки, стала отдельным популярным лакомством.","wiki_en":"Condensed milk"},{"name":"Творожная запеканка","emoji":"🍮","meta":["русская кухня","десерт"],"description":"Запечённая масса из творога, яиц, манки и сахара, часто с изюмом, которая получается плотной снаружи и нежной внутри. Это привычное блюдо детских садов и домашних завтраков на всём постсоветском пространстве.","fact":"Манную крупу в запеканку добавляют не для вкуса, а чтобы творожная масса лучше держала форму при выпечке.","wiki_en":"Tvorog"},{"name":"Ватрушка","emoji":"🥯","meta":["русская кухня","выпечка"],"description":"Круглая сдобная булочка с открытой серединой, заполненной творогом, иногда с изюмом или вареньем. Простая и сытная выпечка традиционно подаётся к чаю и остаётся одной из самых узнаваемых сдоб русской кухни.","fact":"Форма ватрушки с приподнятыми краями и открытой начинкой в середине сложилась ещё в народной выпечке.","wiki_en":"Vatrushka"},{"name":"Шарлотка","emoji":"🍎","meta":["русская кухня","десерт"],"description":"Простой бисквитный пирог с яблоками, тесто для которого замешивают буквально за несколько минут, а фрукты составляют почти половину объёма выпечки. Благодаря лёгкости рецепта это один из самых популярных домашних десертов в русскоязычных семьях.","fact":"Русская шарлотка сильно отличается от английского оригинала — она не содержит хлеба и желе, только бисквит и яблоки.","wiki_en":"Charlotte (cake)"},{"name":"Курник","emoji":"🥧","meta":["русская кухня","выпечка"],"description":"Высокий закрытый пирог из нескольких слоёв начинки — курицы, риса, грибов и блинов, — традиционно украшаемый фигурным тестом сверху. Такой пирог был обязательным блюдом на русских свадьбах, где символизировал достаток и благополучие семьи.","fact":"Название пирога прямо указывает на курицу — без неё курник не считался настоящим.","wiki_en":"Pirog"},{"name":"Рассольник","emoji":"🥒","meta":["русская кухня","суп"],"description":"Суп на основе мясного или рыбного бульона с солёными огурцами, перловой крупой и картофелем, дающий характерный кисловатый вкус. Один из старейших русских супов, чьё название прямо указывает на огуречный рассол в составе.","fact":"Предшественником рассольника считают старинную калью — суп на огуречном рассоле с рыбой или курицей.","wiki_en":"Rassolnik"},{"name":"Гречневая каша","emoji":"🌾","meta":["русская кухня","гарнир"],"description":"Каша из обжаренной гречневой крупы, отваренной до рассыпчатого состояния, традиционно подаётся с маслом как самостоятельное блюдо или гарнир к мясу. В русской кухне гречка занимает особое место как один из самых узнаваемых и любимых злаков.","fact":"Россия исторически остаётся одним из крупнейших в мире производителей и потребителей гречневой крупы.","wiki_en":"Kasha"},{"name":"Манная каша","emoji":"🥣","meta":["русская кухня","завтрак"],"description":"Молочная каша из манной крупы, которую варят до гладкой кремовой консистенции, — классический детский завтрак в русскоязычных семьях. Из-за риска образования комочков её варят, постоянно помешивая и тонкой струйкой всыпая крупу.","fact":"Манная крупа получается при помоле пшеницы на промежуточном этапе, ещё до превращения зерна в тонкую муку.","wiki_en":"Semolina"},{"name":"Бородинский хлеб","emoji":"🍞","meta":["русская кухня","хлеб"],"description":"Тёмный ржаной хлеб с характерным сладковато-пряным вкусом кориандра и патоки, один из самых узнаваемых сортов хлеба в России. Его плотный мякиш и насыщенный аромат делают бородинский хлеб узнаваемым даже среди других ржаных сортов.","fact":"Сверху бородинский хлеб традиционно посыпают целыми зёрнами кориандра или тмина.","wiki_en":"Borodinsky bread"},{"name":"Сало","emoji":"🐷","meta":["русская и украинская кухня","закуска"],"description":"Просоленный или прокопчённый свиной подкожный жир, который едят тонкими ломтиками с хлебом, чесноком и горчицей. Особенно почитаемый продукт украинской кухни, вокруг которого сложилось множество кулинарных традиций и шуток.","fact":"На Украине проводят целые фестивали, посвящённые салу как национальному продукту.","wiki_en":"Salo (food)"},{"name":"Квашеная капуста","emoji":"🥬","meta":["русская кухня","закуска"],"description":"Нашинкованная капуста, заквашенная в собственном соку с солью, иногда с добавлением моркови, яблок или клюквы. Один из самых древних способов заготовки овощей на зиму в русской кухне, ценный ещё и высоким содержанием витамина С.","fact":"Раньше капусту квасили в больших деревянных бочках, а шинковали прямо в корыте специальной сечкой.","wiki_en":"Sauerkraut","wiki_ru":"Квашеная капуста"},{"name":"Солёные огурцы","emoji":"🥒","meta":["русская кухня","закуска"],"description":"Огурцы, заквашенные или засоленные в рассоле со специями — укропом, чесноком и листьями хрена или смородины, — до характерного кисло-солёного вкуса. Традиционная закуска и заготовка на зиму, без которой сложно представить русский стол.","fact":"Рассол от солёных огурцов в народной традиции нередко считали домашним средством от похмелья.","wiki_en":"Pickled cucumber"},{"name":"Маринованные грибы","emoji":"🍄","meta":["русская кухня","закуска"],"description":"Лесные грибы, отваренные и залитые маринадом с уксусом, специями и лавровым листом, — популярная холодная закуска и заготовка на зиму. Сбор и заготовка грибов на Руси традиционно были важной частью осеннего быта.","fact":"Тихая охота — сбор грибов — остаётся одним из самых массовых осенних увлечений в России.","wiki_en":"Pickling"},{"name":"Чёрная икра","emoji":"⚫","meta":["русская кухня","деликатес"],"description":"Солёная икра осетровых рыб, ценимая за нежный маслянистый вкус и крупные тёмные зёрна, — один из самых престижных деликатесов мира. Из-за перелова осетровых её добыча сегодня строго регулируется, что сделало продукт ещё более дорогим.","fact":"Большая часть чёрной икры на прилавках сегодня — от осетров, выращенных на рыбоводных хозяйствах, а не выловленных в море.","wiki_en":"Caviar"},{"name":"Красная икра","emoji":"🟠","meta":["русская кухня","деликатес"],"description":"Икра лососёвых рыб — горбуши, кеты или нерки — с крупными оранжево-красными зёрнами, традиционный деликатес дальневосточной и праздничной русской кухни. Её подают на бутербродах с маслом или как самостоятельную закуску.","fact":"Бутерброд с красной икрой стал одним из главных символов праздничного новогоднего стола в России.","wiki_en":"Salmon roe"},{"name":"Пирожное «Картошка»","emoji":"🍫","meta":["советская кухня","десерт"],"description":"Бисквитное пирожное, измельчённое и смешанное с маслом и какао, а затем слепленное в форме картофелины и обваленное в какао-порошке. Простой рецепт из остатков бисквита сделал его одним из самых доступных десертов советских кулинарий.","fact":"Сверху пирожное часто украшают кремовыми «глазками», подчёркивая сходство с настоящей картошкой.","wiki_en":"Kartoshka"},{"name":"Чак-чак","emoji":"🍯","meta":["татарская кухня","десерт"],"description":"Кусочки жареного во фритюре теста, политые горячим мёдом и слепленные в горку или другую фигурную форму. Это главное праздничное лакомство татарской кухни, обязательное на свадьбах и торжествах.","fact":"В Казани чак-чаку посвящён отдельный музей, где заодно рассказывают о татарском чаепитии.","wiki_en":"Chak-Chak","wiki_ru":"Чак-чак"},{"name":"Эчпочмак","emoji":"🥟","meta":["татарская кухня","выпечка"],"description":"Треугольный пирожок из пресного теста с начинкой из мяса, картофеля и лука, который заливают бульоном через специальное отверстие сверху перед подачей. Его характерная трёхгранная форма и название переводятся с татарского как «треугольник».","fact":"Начинку для эчпочмака не пропускают через мясорубку: мясо и картофель режут мелкими кубиками и кладут сырыми.","wiki_en":"Echpochmak"},{"name":"Беляши","emoji":"🫓","meta":["татарская кухня","выпечка"],"description":"Круглые пирожки из дрожжевого теста с мясной начинкой, которые жарят во фритюре с открытым отверстием сверху, через которое видно мясо. Блюдо тюркского происхождения широко распространилось по всей России как популярный фастфуд.","fact":"Небольшое отверстие сверху беляша оставляют специально, чтобы во время жарки выходил лишний пар.","wiki_en":"Belyash"},{"name":"Пожарские котлеты","emoji":"🍗","meta":["русская кухня","основное блюдо"],"description":"Рубленые котлеты из куриного филе в хрустящей панировке из белого хлеба, названные в честь трактирщицы из города Торжка. По легенде, рецепт настолько понравился императору Николаю I, что котлеты стали известны на всю страну.","fact":"В классическом рецепте в фарш добавляют сливочное масло, а панируют котлеты в кубиках белого хлеба, а не в сухарях.","wiki_en":"Pozharsky cutlet"},{"name":"Форшмак","emoji":"🐟","meta":["еврейская кухня","закуска"],"description":"Паштетообразная закуска из рубленой сельди, яблок, лука и варёных яиц, заправленная маслом до однородной пастообразной массы. Блюдо пришло из ашкеназской еврейской кухни и прочно закрепилось в русской и украинской кулинарной традиции.","fact":"Название блюда происходит от немецкого слова, означающего закуску, подаваемую перед основной трапезой.","wiki_en":"Forshmak"},{"name":"Шурпа","emoji":"🍲","meta":["среднеазиатская кухня","суп"],"description":"Наваристый суп из баранины или говядины с крупно нарезанными овощами — морковью, картофелем и луком, — приправленный пряными травами. Блюдо широко распространено у тюркских и кавказских народов, при этом в каждом регионе есть свой вариант рецепта.","fact":"Овощи в шурпу режут крупно и закладывают ближе к концу варки, чтобы они не разварились в бульоне.","wiki_en":"Shurpa"},{"name":"Баурсак","emoji":"🍩","meta":["казахская кухня","выпечка"],"description":"Небольшие шарики или ромбики из дрожжевого теста, обжаренные во фритюре до золотистой пористой корочки. Традиционное угощение казахской и среднеазиатской кухни, которое подают к чаю и на праздничный стол.","fact":"На казахских праздниках горку баурсаков нередко выкладывают на достархан как обязательное угощение для гостей.","wiki_en":"Baursak"},{"name":"Кумыс","emoji":"🐴","meta":["тюркская кухня","напиток"],"description":"Кисломолочный напиток из кобыльего молока, полученный естественным брожением, — слегка газированный и с лёгким алкогольным градусом. Традиционный напиток кочевых народов степей, который издавна ценили ещё и за предполагаемые целебные свойства.","fact":"В XIX веке кумыс использовали в специальных лечебницах-кумысолечебницах как средство для укрепления здоровья.","wiki_en":"Kumis"},{"name":"Аджика","emoji":"🌶️","meta":["кавказская кухня","соус"],"description":"Острая паста из красного перца, чеснока и пряных трав, которую традиционно готовили абхазские пастухи как приправу к мясу. Сегодня существует множество вариаций аджики, включая более мягкие томатные версии, распространённые на всём Кавказе.","fact":"Классическая абхазская аджика вообще не содержит помидоров — это чисто перечно-чесночная паста.","wiki_en":"Adjika"},{"name":"Сулугуни","emoji":"🧀","meta":["грузинская кухня","сыр"],"description":"Рассольный сыр с плотной слоистой структурой и характерным кисломолочным вкусом, изготавливаемый методом, схожим с моцареллой. Его подают как самостоятельную закуску, а также используют в выпечке — например, в грузинских хачапури.","fact":"Слоистая структура сулугуни получается благодаря особой технологии вытягивания сырной массы в горячей воде.","wiki_en":"Sulguni"},{"name":"Пхали","emoji":"🥬","meta":["грузинская кухня","закуска"],"description":"Холодная закуска из измельчённых овощей — шпината, свёклы или фасоли — смешанных с грецкими орехами, чесноком и пряными травами. Такие шарики или котлетки часто украшают зёрнами граната и подают в начале грузинской трапезы.","fact":"Пхали традиционно готовят из самых разных овощей, поэтому на столе может быть сразу несколько видов разного цвета.","wiki_en":"Pkhali"},{"name":"Аджапсандали","emoji":"🍆","meta":["грузинская кухня","основное блюдо"],"description":"Тушёное овощное рагу из баклажанов, перца, томатов и лука с чесноком и пряными травами, которое готовят без мяса. Простое и яркое блюдо грузинской кухни особенно популярно в тёплое время года, когда овощи наиболее свежие.","fact":"Несмотря на плотность блюда, аджапсандали традиционно полностью вегетарианское.","wiki_en":"Ajapsandali"},{"name":"Карривурст","emoji":"🌭","meta":["немецкая кухня","уличная еда"],"description":"Жареная свиная сосиска, нарезанная кусочками и политая кетчупом с карри-порошком, — одна из самых популярных уличных закусок Германии. Блюдо появилось в послевоенном Берлине и с тех пор стало неотъемлемой частью немецкого фастфуда.","fact":"Придумала блюдо берлинская торговка Херта Хойер, смешавшая в 1949 году кетчуп с порошком карри.","wiki_en":"Currywurst"},{"name":"Дёнер-кебаб","emoji":"🥙","meta":["турецко-немецкая кухня","уличная еда"],"description":"Тонкие ломтики мяса, срезанные с вертикального вертела, подаются в лепёшке или лаваше с овощами и соусом. Блюдо турецкого происхождения приобрело особую популярность в Германии, где его адаптировали для быстрого уличного перекуса.","fact":"В Германии дёнер обычно подают в разрезанной лепёшке, а в Турции чаще заворачивают в тонкий лаваш.","wiki_en":"Döner kebab"},{"name":"Крок-месье","emoji":"🥪","meta":["французская кухня","сэндвич"],"description":"Горячий сэндвич из ветчины и расплавленного сыра грюйер между двумя ломтиками хлеба, часто дополнительно запечённый под соусом бешамель. Классика французских кафе, которую подают как в бистро, так и в качестве домашней закуски.","fact":"Если сверху положить жареное яйцо, сэндвич превращается в другое блюдо — «крок-мадам».","wiki_en":"Croque monsieur"},{"name":"Штоллен","emoji":"🎄","meta":["немецкая кухня","выпечка"],"description":"Плотный рождественский хлеб с сухофруктами, орехами и пряностями, обильно посыпанный сахарной пудрой сверху. Традиция выпекать штоллен на Рождество в Германии насчитывает несколько веков и особенно сильна в городе Дрездене.","fact":"В Дрездене ежегодно проводят фестиваль штоллена с выпечкой гигантского праздничного каравая.","wiki_en":"Stollen"},{"name":"Марципан","emoji":"🌰","meta":["европейская кухня","десерт"],"description":"Сладкая масса из молотого миндаля и сахарной пудры, из которой лепят фигурки или используют как начинку для конфет и выпечки. Особенно славится марципан из немецкого города Любека, где его производство стало местной традицией.","fact":"Городу Любеку марципан принёс такую известность, что его называют неофициальной столицей этого лакомства.","wiki_en":"Marzipan"},{"name":"Глинтвейн","emoji":"🍷","meta":["европейская кухня","напиток"],"description":"Красное вино, подогретое со специями — корицей, гвоздикой и цитрусовыми, — которое традиционно пьют на европейских рождественских ярмарках в холодное время года. Тёплый пряный напиток стал одним из главных символов зимних праздников в Европе.","fact":"Название «глинтвейн» происходит от немецкого словосочетания, означающего «раскалённое вино».","wiki_en":"Mulled wine"},{"name":"Айран","emoji":"🥛","meta":["кавказская кухня","напиток"],"description":"Кисломолочный напиток из разбавленного водой йогурта или кефира с добавлением соли, широко распространённый на Кавказе и в Средней Азии. Его пьют в жару как освежающий и утоляющий жажду напиток, часто подают к мясным блюдам.","fact":"В разных тюркских странах похожие напитки называют по-разному, хотя рецепт остаётся почти одинаковым.","wiki_en":"Ayran"},{"name":"Кефир","emoji":"🥛","meta":["кавказская кухня","напиток"],"description":"Кисломолочный напиток, полученный брожением молока при помощи особых кефирных грибков — симбиоза бактерий и дрожжей. По легенде, рецепт долгое время держали в секрете горцы Северного Кавказа, откуда напиток распространился по всей России.","fact":"Из-за работы дрожжей в кефире образуются углекислый газ и совсем немного спирта, поэтому он слегка щиплет язык.","wiki_en":"Kefir"},{"name":"Ряженка","emoji":"🥛","meta":["украинская кухня","напиток"],"description":"Кисломолочный напиток из томлённого в печи молока, заквашенного специальными культурами до кремовой консистенции и характерного бежевого цвета. Традиционный напиток украинской и русской кухни отличается от кефира более мягким, сливочным вкусом.","fact":"В деревенской традиции молоко для ряженки часами держали в глиняном горшке в остывающей печи.","wiki_en":"Ryazhenka"},{"name":"Глазированный сырок","emoji":"🍫","meta":["советская кухня","десерт"],"description":"Брикет творожной массы с добавками, покрытый тонким слоем шоколадной глазури, — популярный молочный десерт советской и постсоветской пищевой промышленности. Компактная форма и сладкий вкус сделали его любимым детским лакомством на протяжении десятилетий.","fact":"Такие творожные сырки в глазури массово выпускают не только в России, но и в Латвии, Литве и Эстонии.","wiki_en":"Curd snack","wiki_ru":"Творожный сырок"},{"name":"Пломбир","emoji":"🍦","meta":["советская кухня","десерт"],"description":"Плотное сливочное мороженое с высоким содержанием молочного жира и минимальным количеством воздуха, что делает его особенно насыщенным на вкус. В СССР пломбир изготавливали по строгому единому стандарту, из-за чего вкус оставался практически одинаковым по всей стране.","fact":"Название связывают с французским курортным городком Пломбьер-ле-Бен, где готовили похожий десерт.","wiki_en":"Plombir"},{"name":"Лимонад «Тархун»","emoji":"🌿","meta":["грузинская кухня","напиток"],"description":"Газированный лимонад ярко-зелёного цвета со вкусом эстрагона, придуманный грузинским фармацевтом как тонизирующий напиток. Его характерный оттенок и пряно-травяной вкус делают напиток легко узнаваемым среди других советских лимонадов.","fact":"Ярко-зелёный оттенок напитку даёт краситель: сам настой эстрагона такого цвета не даёт.","wiki_en":"Tarkhun"},{"name":"Лимонад «Дюшес»","emoji":"🍐","meta":["советская кухня","напиток"],"description":"Газированный лимонад со вкусом груши сорта дюшес, один из самых узнаваемых советских безалкогольных напитков наравне с «Тархуном» и «Байкалом». Его мягкий сладкий вкус и характерный жёлтый цвет сделали напиток популярным на протяжении десятилетий.","fact":"Лимонад разливали по единым советским рецептурам, и его до сих пор выпускают в странах бывшего СССР.","wiki_en":"Duchess (drink)"},{"name":"Рутбир","emoji":"🥤","meta":["американская кухня","напиток"],"description":"Газированный напиток с характерным вкусом корня сассафраса и других трав, изначально готовившийся как слабоалкогольный, а позже ставший безалкогольным. Его специфический «медицинский» вкус часто вызывает у людей, не выросших в США, противоречивую реакцию.","fact":"Из-за запрета сафрола рутбир давно готовят не на настоящем корне сассафраса, а на ароматизаторах.","wiki_en":"Root beer"},{"name":"Гоголь-моголь","emoji":"🥚","meta":["восточноевропейская кухня","десерт"],"description":"Взбитые с сахаром яичные желтки, иногда с добавлением молока или рома, которые едят ложкой или пьют как питательный десерт-напиток. В народной традиции его нередко использовали как домашнее средство при простуде и боли в горле.","fact":"Близкий родственник гоголь-моголя — американский эгног: те же взбитые желтки с сахаром, молоком и ромом.","wiki_en":"Gogol-mogol"},{"name":"Кальцоне","emoji":"🥟","meta":["итальянская кухня","выпечка"],"description":"Закрытый пирог из пиццевого теста, сложенный пополам вокруг начинки из сыра, ветчины и других ингредиентов, а затем запечённый или обжаренный. По сути это «пицца наизнанку» родом из Неаполя, удобная для еды на ходу.","fact":"Название «кальцоне» с итальянского можно перевести как «штанина» — из-за вытянутой формы пирога.","wiki_en":"Calzone"},{"name":"Фокачча","emoji":"🫒","meta":["итальянская кухня","хлеб"],"description":"Плоский дрожжевой хлеб, обильно политый оливковым маслом и посыпанный крупной солью, розмарином или другими травами перед выпечкой. Характерные вмятины пальцами на поверхности теста — часть традиционной техники приготовления.","fact":"В Лигурии фокаччу едят даже на завтрак, обмакивая ломтики прямо в капучино.","wiki_en":"Focaccia"},{"name":"Панеттоне","emoji":"🍞","meta":["итальянская кухня","выпечка"],"description":"Высокий сдобный кулич с сухофруктами и цукатами, который в Италии традиционно пекут и едят на Рождество. Долгий процесс выбраживания теста делает мякиш особенно воздушным и лёгким, несмотря на внушительный размер выпечки.","fact":"Настоящий миланский панеттоне может готовиться несколько дней подряд из-за долгого процесса брожения теста.","wiki_en":"Panettone"},{"name":"Тортеллини","emoji":"🍝","meta":["итальянская кухня","паста"],"description":"Маленькие кольца пасты с начинкой из мяса или сыра, слепленные вручную в характерную форму, напоминающую миниатюрное кольцо. По легенде, их форма была вдохновлена пупком прекрасной женщины, которого повар якобы подсмотрел через замочную скважину.","fact":"В Эмилии-Романье тортеллини подают не с соусом, а в крепком мясном бульоне — тортеллини ин бродо.","wiki_en":"Tortellini"},{"name":"Паста песто","emoji":"🧄","meta":["итальянская кухня","паста"],"description":"Паста, заправленная соусом из базилика, кедровых орехов, чеснока, пармезана и оливкового масла, растёртых до однородной ароматной массы. Классический соус родом из Генуи, где базилик считается особенно ароматным благодаря местному климату.","fact":"Традиционный песто по-генуэзски готовят, растирая ингредиенты в мраморной ступке деревянным пестиком, а не блендером.","wiki_en":"Pesto"},{"name":"Торт «Захер»","emoji":"🍫","meta":["австрийская кухня","десерт"],"description":"Шоколадный бисквитный торт с прослойкой абрикосового джема, покрытый плотной шоколадной глазурью, созданный в венской гостинице «Захер». Вокруг точного оригинального рецепта долгое время велась судебная тяжба между кондитерскими за право называть его «настоящим».","fact":"Первую версию торта приготовил в 1832 году юный кондитер Франц Захер, служивший на кухне князя Меттерниха.","wiki_en":"Sachertorte"},{"name":"Тамале","emoji":"🌽","meta":["мексиканская кухня","основное блюдо"],"description":"Кукурузное тесто маса с начинкой из мяса, сыра или овощей, завёрнутое в кукурузный лист или лист банана и приготовленное на пару. Блюдо с многовековой историей, уходящей корнями к древним цивилизациям Месоамерики.","fact":"Перед Рождеством в Мексике тамале лепят большими семейными компаниями — такие посиделки называют тамалада.","wiki_en":"Tamale"},{"name":"Энчилада","emoji":"🌯","meta":["мексиканская кухня","основное блюдо"],"description":"Кукурузная тортилья, свёрнутая вокруг начинки из мяса или сыра и залитая острым соусом чили, а затем запечённая. Одно из основных блюд мексиканской кухни, встречающееся в десятках региональных вариаций по всей стране.","fact":"В разных регионах Мексики энчиладу готовят с совершенно разными соусами — от красного до зелёного и мясного моле.","wiki_en":"Enchilada"},{"name":"Хаггис","emoji":"🐑","meta":["шотландская кухня","основное блюдо"],"description":"Бараний рубец, начинённый смесью из субпродуктов, овсянки, лука и специй, а затем сваренный на пару, — национальное блюдо Шотландии. Его традиционно подают на ужин Бёрнса в честь дня рождения поэта Роберта Бёрнса, который посвятил хаггису отдельную оду.","fact":"Из-за запрета на использование бараньих лёгких в еде настоящий шотландский хаггис долгие годы нельзя было ввозить в США.","wiki_en":"Haggis"},{"name":"Йоркширский пудинг","emoji":"🍞","meta":["английская кухня","гарнир"],"description":"Воздушная выпечка из жидкого теста на основе яиц, муки и молока, которую запекают в раскалённом жире до пышного пузырчатого купола. Традиционно подаётся как гарнир к воскресному жаркому из говядины в классическом английском обеде.","fact":"Раньше йоркширский пудинг подавали перед основным блюдом отдельно, чтобы гости меньше съедали дорогого мяса.","wiki_en":"Yorkshire pudding"},{"name":"Бисквит «Виктория»","emoji":"🎂","meta":["английская кухня","десерт"],"description":"Классический английский бисквитный торт из двух коржей, переслоённых вареньем и взбитыми сливками, названный в честь королевы Виктории. Простота и элегантность рецепта сделали его неотъемлемой частью традиционного английского чаепития.","fact":"Классический рецепт строится на равных по весу частях масла, сахара, муки и яиц — его легко запомнить.","wiki_en":"Victoria sponge"},{"name":"Тост с авокадо","emoji":"🥑","meta":["интернациональная кухня","завтрак"],"description":"Ломтик подсушенного хлеба, щедро намазанный размятым авокадо с солью, перцем и лимонным соком, часто дополненный яйцом-пашот. Блюдо стало символом современной кофейни и модного завтрака, особенно популярным в социальных сетях 2010-х годов.","fact":"Авокадо для тоста нужно мягкое: плоды срывают твёрдыми и доводят до спелости уже после сбора.","wiki_en":"Avocado toast"},{"name":"Ирландское рагу","emoji":"🥘","meta":["ирландская кухня","основное блюдо"],"description":"Наваристое тушёное блюдо из баранины или говядины с картофелем, луком и морковью, томящееся на медленном огне до полной мягкости мяса. Простое крестьянское блюдо стало неофициальным национальным блюдом Ирландии.","fact":"Классический рецепт ирландского рагу считается настолько простым, что в нём принципиально нет никаких экзотических специй.","wiki_en":"Irish stew"},{"name":"Пряничный человечек","emoji":"🍪","meta":["европейская кухня","выпечка"],"description":"Фигурное пряничное печенье в форме человечка, украшенное сахарной глазурью, традиционно связанное с зимними и рождественскими праздниками в Европе и США. Его образ хорошо знаком и по детским сказкам, где убегающий пряничный человечек становится героем сюжета.","fact":"Тесто для таких печений делают плотным, на меду или сиропе с корицей и гвоздикой, чтобы фигурка держала форму.","wiki_en":"Gingerbread man"},{"name":"Крем-карамель","emoji":"🍮","meta":["французская кухня","десерт"],"description":"Нежный яичный крем, запечённый на водяной бане и перевёрнутый перед подачей так, чтобы сверху оказался слой жидкой карамели. Десерт распространён по всему миру под разными названиями, от французского флана до испанского и латиноамериканского варианта.","fact":"Карамель заливают на дно формы ещё до крема, и при переворачивании она стекает по десерту как соус.","wiki_en":"Crème caramel"},{"name":"Кулич","emoji":"🐣","meta":["русская кухня","выпечка"],"description":"Высокий сдобный цилиндрический хлеб с изюмом и цукатами, покрытый сахарной глазурью сверху, — главная пасхальная выпечка в русской традиции. Его освящают в церкви вместе с творожной пасхой и крашеными яйцами перед праздничным разговением.","fact":"Тесто для кулича очень сдобное — с обилием яиц, масла и сахара, поэтому поднимается оно медленно и долго.","wiki_en":"Kulich","wiki_ru":"Кулич"},{"name":"Творожная пасха","emoji":"🍰","meta":["русская кухня","десерт"],"description":"Десерт из протёртого творога, масла, сахара и сухофруктов, спрессованный в форме усечённой пирамиды при помощи специальной пасхальницы. Традиционно на его гранях выдавливают символы православной Пасхи — крест и буквы «ХВ».","fact":"Пасху не выпекают: творожную массу выдерживают в форме под грузом, чтобы ушла лишняя влага.","wiki_en":"Paskha"},{"name":"Оладьи","emoji":"🥞","meta":["русская кухня","завтрак"],"description":"Небольшие пышные лепёшки из дрожжевого или кефирного теста, обжаренные на сковороде и поданные со сметаной, вареньем или мёдом. Более толстые и пышные, чем блины, оладьи остаются одним из самых привычных вариантов домашнего завтрака.","fact":"Чаще всего тесто для оладий замешивают на кефире с содой — от этого они получаются пористыми внутри.","wiki_en":"Oladyi"},{"name":"Пудинг рисовый","emoji":"🍚","meta":["интернациональная кухня","десерт"],"description":"Рис, томлённый в молоке с сахаром и ванилью до кремовой консистенции, иногда с добавлением изюма или корицы. Подобные десерты из риса и молока встречаются в кухнях многих стран мира под разными названиями.","fact":"В Скандинавии это рождественское блюдо: в порции прячут один миндальный орешек, и нашедшему обещают удачу.","wiki_en":"Rice pudding"},{"name":"Овсяная каша","emoji":"🥣","meta":["британская кухня","завтрак"],"description":"Каша из овсяных хлопьев или цельной крупы, сваренная на воде или молоке до мягкой густой консистенции, — один из самых распространённых вариантов завтрака в мире. В Шотландии и Англии её издавна считают основой сытного утреннего рациона.","fact":"В Шотландии существуют официальные соревнования по варке овсяной каши по старинным правилам.","wiki_en":"Porridge"},{"name":"Мюсли","emoji":"🌾","meta":["швейцарская кухня","завтрак"],"description":"Смесь овсяных хлопьев, орехов и сухофруктов, которую едят с молоком или йогуртом, придумана швейцарским врачом как часть здорового питания пациентов. Сегодня это один из самых распространённых вариантов быстрого и полезного завтрака во всём мире.","fact":"Автор рецепта — врач Максимилиан Бирхер-Беннер, поэтому оригинальный вариант называют бирхермюсли.","wiki_en":"Muesli"},{"name":"Гранола","emoji":"🥄","meta":["американская кухня","завтрак"],"description":"Запечённая до хрустящей корочки смесь овсяных хлопьев, орехов и мёда, которую едят с молоком, йогуртом или отдельно как снек. Изначально придуманная как диетическое блюдо, сегодня гранола стала популярным продуктом здорового питания.","fact":"Название «гранола» закрепил Джон Харви Келлог, работавший в американском санатории Батл-Крик.","wiki_en":"Granola"},{"name":"Смузи","emoji":"🍓","meta":["интернациональная кухня","напиток"],"description":"Густой напиток из взбитых в блендере фруктов, ягод или овощей, иногда с добавлением йогурта или молока. Популярность смузи резко выросла с распространением моды на здоровое питание и удобные быстрые перекусы на ходу.","fact":"Само слово smoothie пришло из английского и указывает на однородную, «гладкую» текстуру напитка.","wiki_en":"Smoothie"},{"name":"Наггетсы куриные","emoji":"🐔","meta":["американская кухня","снек"],"description":"Небольшие кусочки куриного филе в панировке, обжаренные во фритюре до хрустящей корочки, ставшие одним из главных продуктов фастфуда во всём мире. Их компактная форма и универсальность сделали блюдо особенно популярным у детей.","fact":"Технологию наггетсов из измельчённого куриного мяса разработал в 1960-е учёный из Корнеллского университета Роберт Бейкер.","wiki_en":"Chicken nugget"}];
